const NAV=[['dashboard','⌂','Overview'],['staff','🛡️','Staff'],['vehicles','🚗','Vehicles'],['insurance','🛡️','Insurance'],['taxi','🚁','Airlift Taxi'],['rental','🏍️','Dirtbike'],['shop','🛒','Server Shop'],['events','📅','Events'],['playershops','🏪','Player Shops'],['squads','👥','Squad Finder'],['lore','📖','Player Lore'],['history','🧾','History'],['account','👤','Account']];
const ADMIN=[['admin','⚙️','Admin Tools'],['surveillance','👁️','Surveillance']];
const OWNER=[['owner','🔒','Owner Tools']];
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
let state={me:null,data:null,section:new URLSearchParams(location.search).get('section')||sessionStorage.getItem('watcherPortalSection')||'dashboard',navHistory:[],sessionExpiresAt:0,sessionTimer:null,sessionWarningShown:false,sessionExpired:false,overviewHash:'',portalRevision:0,autoRefreshTimer:null,revisionStream:null,lastAutoRefreshAt:0,adminSubtab:'players',adminLedger:{page:1,pageSize:25,category:'all',status:'all',search:'',total:0,pages:1,rows:[]},busyCount:0,selectedAdminPlayer:null,pendingPortalRefresh:false,userInteractingUntil:0,deferredRefreshTimer:null};
const DRAFT_PREFIX='watcherPortalDraft:';
function confirmWatcherAction({action,player='',steamId='',details=''}){const lines=[`Action: ${action}`,player?`Player: ${player}`:'',steamId?`Steam64: ${steamId}`:'',details?`Details: ${details}`:'','',`Confirm ${action}?`].filter(Boolean);return confirm(lines.join('\n'))}
function groupedAdminTiles(tiles){return `<div class="adminToolStrip" role="toolbar" aria-label="Admin tools">${tiles.join('')}</div>`}
function toggleAdminGroup(){/* retained for backward-compatible cached portal markup */}
function filterAdminTools(){const q=($('adminToolSearch')?.value||'').trim().toLowerCase();let visible=0;document.querySelectorAll('.adminToolStrip .mobileAdminTile').forEach(tile=>{const show=!q||tile.textContent.toLowerCase().includes(q);tile.hidden=!show;if(show)visible++});const empty=$('adminToolEmpty');if(empty)empty.hidden=visible>0}
function markAdminToolActive(tab){document.querySelectorAll('.mobileAdminTile').forEach(tile=>tile.classList.toggle('active',String(tile.getAttribute('onclick')||'').includes(`adminTab('${tab}')`)))}
function mutationMethod(opt={}){return String(opt.method||'GET').toUpperCase()}
function setBusy(on,text='Watcher is processing…'){state.busyCount=Math.max(0,state.busyCount+(on?1:-1));const active=state.busyCount>0;document.body.classList.toggle('isBusy',active);$('globalBusy')?.classList.toggle('hidden',!active);if(active&&$('globalBusyText'))$('globalBusyText').textContent=text}
async function api(path,opt={}){const method=mutationMethod(opt),mutation=['POST','PUT','PATCH','DELETE'].includes(method);if(mutation)setBusy(true,opt.busyText||'Watcher is processing your request…');try{const r=await fetch(path,{...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});const renewed=r.headers.get('X-Watcher-Session-Expires');if(renewed)startSessionClock(renewed);const j=await r.json().catch(()=>({}));if(r.status===401){expireSession();throw new Error('Your secure session has expired. Please reopen the Command Center from Discord.')}if(!r.ok)throw new Error(j.error||'Watcher request failed');if(mutation){if(j.verified===false||j.completed===false)throw new Error(j.error||j.message||'Watcher could not verify completion.');j.verified=true;j.completed=true;j.verificationMessage=j.verificationMessage||j.verification?.message||j.message||'Watcher verified the task completed.';try{localStorage.setItem('watcherPortalUpdate',JSON.stringify({at:Date.now(),path}))}catch{}}return j}finally{if(mutation)setBusy(false)}}
function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(n||0))}
function fmt(t){return t?new Date(t).toLocaleString():'—'}
function toast(s){const e=$('toast');e.textContent=s;e.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>e.style.display='none',3500)}
function weatherIcon(w){if(Number(w?.lightningRate||0)>0)return '⚡';if(Number(w?.snowIntensity||0)>0.05)return '❄️';if(Number(w?.rainIntensity||0)>0.05)return '🌧️';if(w?.fogEnabled||Number(w?.fogDensity||0)>0.5)return '🌫️';if(String(w?.dayPeriod||'').toLowerCase()==='night')return '🌙';return '☀️'}
async function loadServerWeather(){const box=$('serverWeather');if(!box)return;try{const w=await api('/portal/api/weather');const temp=Number.isFinite(Number(w.airTemperature))?`${Number(w.airTemperature).toFixed(1)}°C`:'Temp unavailable';const wind=Number.isFinite(Number(w.windSpeedKph))?`${Number(w.windSpeedKph).toFixed(0)} km/h wind`:'Wind unavailable';box.innerHTML=`<span class="weatherIcon">${weatherIcon(w)}</span><div><small>SCUM WEATHER</small><b>${esc(temp)} • ${esc(w.dayPeriod||'Server')}</b><em>${esc(wind)}</em></div>`;box.title=`Rain ${Math.round(Number(w.rainIntensity||0)*100)}% • Fog ${Math.round(Number(w.fogDensity||0)*100)}%`}catch(e){box.innerHTML='<span class="weatherIcon">◌</span><div><small>SCUM WEATHER</small><b>Unavailable</b><em>GGCON weather offline</em></div>'}}
function draftKey(name){const who=state.me?.discordId||state.me?.id||state.me?.displayName||'user';return `${DRAFT_PREFIX}${who}:${name}`}
function saveDraft(name,extra={}){const modal=$('modal');if(!modal||modal.classList.contains('hidden'))return;const values={};modal.querySelectorAll('input:not([type=file]),textarea,select').forEach(el=>{if(!el.id)return;values[el.id]=el.type==='checkbox'?el.checked:el.value});try{localStorage.setItem(draftKey(name),JSON.stringify({savedAt:Date.now(),section:state.section,values,...extra}))}catch{}}
function readDraft(name,maxAge=604800000){try{const raw=localStorage.getItem(draftKey(name));if(!raw)return null;const d=JSON.parse(raw);if(!d?.savedAt||Date.now()-d.savedAt>maxAge){localStorage.removeItem(draftKey(name));return null}return d}catch{return null}}
function clearDraft(name){try{localStorage.removeItem(draftKey(name))}catch{}}
function restoreDraft(name,{extraRestore}={}){const d=readDraft(name);if(!d)return false;for(const [id,val] of Object.entries(d.values||{})){const el=$(id);if(!el)continue;if(el.type==='checkbox')el.checked=!!val;else el.value=val}if(extraRestore)extraRestore(d);toast(`Recovered your unsaved work from ${new Date(d.savedAt).toLocaleTimeString()}.`);return true}
function armDraft(name,extraProvider){const modal=$('modal');if(!modal)return;const save=()=>saveDraft(name,typeof extraProvider==='function'?extraProvider():{});modal.querySelectorAll('input,textarea,select').forEach(el=>{if(el.type==='file')return;el.addEventListener('input',save);el.addEventListener('change',save)});saveDraft.active={name,save}}
function modalBusy(){const modal=$('modal');if(modal&&!modal.classList.contains('hidden'))return true;const a=document.activeElement;return !!a&&['INPUT','TEXTAREA','SELECT'].includes(a.tagName)}
function stableHash(data){try{return JSON.stringify(data)}catch{return String(Date.now())}}
function preserveUi(){return {scrollY:window.scrollY,filter:$('filter')?.value||'',shopManagerFilter:$('shopManagerFilter')?.value||'',adminSubtab:state.adminSubtab,adminSearch:$('adminSearch')?.value||'',selectedAdminPlayer:state.selectedAdminPlayer}}
function restoreUi(ui){if(ui.filter&&$('filter')){$('filter').value=ui.filter;filterCards()}if(ui.shopManagerFilter&&$('shopManagerFilter')){$('shopManagerFilter').value=ui.shopManagerFilter;filterShopManagerCards()}if(ui.adminSearch&&$('adminSearch'))$('adminSearch').value=ui.adminSearch;if(ui.selectedAdminPlayer&&state.section==='admin'&&state.adminSubtab==='players')setTimeout(()=>openAdminPlayer(ui.selectedAdminPlayer.steamId,ui.selectedAdminPlayer.name),0);requestAnimationFrame(()=>window.scrollTo(0,ui.scrollY||0))}
function autoRefreshSafeSection(){return state.section==='dashboard'}
async function silentRefresh(force=false,allowDisrupt=false){if(state.sessionExpired||document.hidden||(!force&&modalBusy()))return;/* Automatic live updates may only rebuild the passive dashboard. Every tool, store, form, event page, account page, and admin view is manual-refresh only so Watcher can never interrupt a purchase, lookup, selection, or scroll position. Explicit action refreshes still update immediately after the action completes. */if(!allowDisrupt&&!autoRefreshSafeSection()){state.pendingPortalRefresh=true;return}if(!allowDisrupt&&Date.now()<state.userInteractingUntil){state.pendingPortalRefresh=true;clearTimeout(state.deferredRefreshTimer);state.deferredRefreshTimer=setTimeout(()=>silentRefresh(true,false),5500);return}try{if(!force){const rev=await api('/portal/api/revision');if(Number(rev.revision||0)===Number(state.portalRevision||0))return;state.portalRevision=Number(rev.revision||0)}const fresh=await api('/portal/api/overview');const ui=preserveUi();state.data=fresh;state.me=fresh.me;state.overviewHash=stableHash(fresh);nav();render();renderMaintenance();restoreUi(ui);state.lastAutoRefreshAt=Date.now();state.pendingPortalRefresh=false}catch(e){if(!state.sessionExpired)console.warn('Portal auto-refresh skipped:',e.message)}}

function markPortalInteraction(){state.userInteractingUntil=Date.now()+5000}
window.addEventListener('scroll',markPortalInteraction,{passive:true});
window.addEventListener('pointerdown',markPortalInteraction,{passive:true});
window.addEventListener('keydown',markPortalInteraction);
function startAutoRefresh(){
  clearInterval(state.autoRefreshTimer);
  state.revisionStream?.close?.();
  try{
    const stream=new EventSource('/portal/api/stream');state.revisionStream=stream;
    stream.addEventListener('revision',e=>{try{const x=JSON.parse(e.data||'{}');if(Number(x.value||0)!==Number(state.portalRevision||0)){state.portalRevision=Number(x.value||0);silentRefresh(true)}}catch{silentRefresh(true)}});
    stream.onerror=()=>{stream.close();state.revisionStream=null;clearInterval(state.autoRefreshTimer);state.autoRefreshTimer=setInterval(()=>silentRefresh(false),180000)};
  }catch{state.autoRefreshTimer=setInterval(()=>silentRefresh(false),180000)}
}
window.addEventListener('storage',e=>{if(e.key==='watcherPortalUpdate')silentRefresh(true)});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)silentRefresh(false)});
window.addEventListener('beforeunload',()=>{state.revisionStream?.close?.();try{sessionStorage.setItem('watcherPortalSection',state.section);sessionStorage.setItem('watcherPortalScroll',String(window.scrollY))}catch{}if(saveDraft.active?.save)saveDraft.active.save()});
function formatRemaining(ms){const total=Math.max(0,Math.ceil(ms/1000)),m=Math.floor(total/60),sec=total%60;return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}
function startSessionClock(expiresAt){state.sessionExpiresAt=Date.parse(expiresAt||'');if(!Number.isFinite(state.sessionExpiresAt))return;clearInterval(state.sessionTimer);updateSessionClock();state.sessionTimer=setInterval(updateSessionClock,60000)}
function updateSessionClock(){if(state.sessionExpired)return;const left=state.sessionExpiresAt-Date.now();const label=$('sessionState');if(label)label.textContent=left>0?`Session ${formatRemaining(left)}`:'Session expired';const countdown=$('sessionWarningCountdown');if(countdown)countdown.textContent=`${formatRemaining(left)} remaining`;if(left<=0){expireSession();return}if(left<=5*60*1000&&!state.sessionWarningShown){state.sessionWarningShown=true;$('sessionWarning')?.classList.remove('hidden')}}
function dismissSessionWarning(){$('sessionWarning')?.classList.add('hidden')}
function expireSession(){if(state.sessionExpired)return;if(saveDraft.active?.save)saveDraft.active.save();try{sessionStorage.setItem('watcherPortalSection',state.section);sessionStorage.setItem('watcherPortalScroll',String(window.scrollY))}catch{}state.sessionExpired=true;clearInterval(state.sessionTimer);document.body.innerHTML=`<main class="expiredScreen"><div class="sessionPanel expiredPanel"><img src="/portal/assets/watcher.jpg" alt="The Watcher"><span class="sessionKicker">SECURE CONNECTION CLOSED</span><h1>Command Center Session Expired</h1><p>Your secure access window has ended and all Command Center actions are now disabled.</p><strong>Please reopen the Command Center from Discord.</strong><div class="sessionActions"><a class="btn primary" href="https://discord.com/channels/1516269432538661025/1531709557997306027" target="_blank" rel="noopener">Open Discord Command Center</a><button class="btn" id="closeExpiredWindow">Close Window</button></div><small>Your unsaved draft was preserved. Use the permanent Discord button to reopen the Command Center and continue.</small></div></main>`;document.getElementById('closeExpiredWindow')?.addEventListener('click',()=>window.close())}

function nav(){const adminRows=state.me?.isAdmin?ADMIN.filter(([id])=>id!=='surveillance'||state.me?.isOwner||state.me?.permissions?.use_surveillance):[];const ownerRows=state.me?.isOwner?OWNER:[];const rows=[...NAV,...adminRows,...ownerRows];$('nav').innerHTML=rows.map(([id,ic,l])=>`<button class="${id===state.section?'active':''}" onclick="go('${id}')">${ic}<span>${l}</span></button>`).join('');renderMobileNav();const build=$('portalBuild');if(build&&state.data?.build)build.textContent=`Watcher ${state.data.build.version} • ${state.data.build.deployment}`}
function renderMobileNav(){const rows=state.me?.isAdmin?[['dashboard','⌂','Home'],['vehicles','🚗','Vehicles'],['taxi','🚁','Services'],['events','📅','Events'],['admin','⚙️','Admin']]:[['dashboard','⌂','Home'],['vehicles','🚗','Vehicles'],['taxi','🚁','Services'],['events','📅','Events'],['account','👤','Account']];const box=$('mobileNav');if(box)box.innerHTML=rows.map(([id,ic,l])=>`<button class="${id===state.section?'active':''}" onclick="go('${id}')"><i>${ic}</i><span>${l}</span>${id==='admin'&&Number(state.data?.attention?.total||0)>0?`<em class="navBadge">${Math.min(99,Number(state.data.attention.total))}</em>`:''}</button>`).join('')}
function renderMaintenance(){const notice=state.data?.system?.maintenance;const box=$('maintenanceBanner');if(!box)return;if(!notice?.message||sessionStorage.getItem('watcherMaintenanceDismissed')===notice.id){box.classList.add('hidden');return}$('maintenanceTitle').textContent=notice.title||'WATCHER NOTICE';$('maintenanceText').textContent=notice.message;box.dataset.level=notice.level||'notice';box.classList.remove('hidden')}
function dismissMaintenance(){const box=$('maintenanceBanner');if(state.data?.system?.maintenance?.id)sessionStorage.setItem('watcherMaintenanceDismissed',state.data.system.maintenance.id);box?.classList.add('hidden')}
async function load(){state.data=await api('/portal/api/overview');state.me=state.data.me;state.overviewHash=stableHash(state.data);try{const rev=await api('/portal/api/revision');state.portalRevision=Number(rev.revision||0)}catch{}$('displayName').textContent=state.me.displayName;$('roleText').textContent=state.me.isOwner?'OWNER EYES ONLY':state.me.isAdmin?'ADMIN CLEARANCE':'THE EXILES CLEARANCE';$('avatar').src=state.me.avatar||'/portal/assets/watcher.jpg';startSessionClock(state.me.sessionExpiresAt);nav();render();renderMaintenance();startAutoRefresh();setTimeout(()=>{const y=Number(sessionStorage.getItem('watcherPortalScroll')||0);window.scrollTo(0,y);$('boot').classList.add('hide')},500)}
function updatePageNav(){const back=$('backBtn'),home=$('homeBtn');if(back)back.disabled=!state.navHistory.length;if(home)home.disabled=state.section==='dashboard'}
function go(id,opt={}){if(!id||id===state.section){updatePageNav();return}if(!opt.fromBack){state.navHistory.push(state.section);if(state.navHistory.length>30)state.navHistory.shift()}if(id!=='admin')state.selectedAdminPlayer=null;state.section=id;try{sessionStorage.setItem('watcherPortalSection',id)}catch{}history.replaceState({section:id},'',`/portal?section=${id}`);nav();render();renderMaintenance();updatePageNav();window.scrollTo({top:0,behavior:opt.instant?'auto':'smooth'});if(state.pendingPortalRefresh&&!state.selectedAdminPlayer)setTimeout(()=>silentRefresh(true,false),250)}
function goBack(){const id=state.navHistory.pop()||'dashboard';go(id,{fromBack:true})}
function goHome(){go('dashboard')}
function title(a,b){$('sectionEyebrow').textContent=a;$('sectionTitle').textContent=b}
function metric(label,val,sub=''){return `<div class="card span3 metric"><small>${label}</small><b>${val}</b><span>${sub}</span></div>`}
function service(id,ic,name,desc,status='Open'){return `<div class="card span4 service" onclick="go('${id}')"><i>${ic}</i><h3>${name}</h3><p>${desc}</p><div style="margin-top:12px"><span class="status good">${status}</span></div></div>`}
function render(){const d=state.data||{};const p=d.player||{};const v=$('view');if(state.section==='dashboard'){title('WATCHER OVERVIEW','Command Dashboard');v.innerHTML=`<div class="grid">${d.settings?.announcement?`<div class="card span12 portalAnnouncement"><small>WATCHER ANNOUNCEMENT</small><h3>${esc(d.settings.announcement)}</h3></div>`:''}${metric('SCUM Character',esc(p.name||'Not linked'),p.online?'ONLINE NOW':'OFFLINE')}${metric('Cash',p.cash==null?'—':money(p.cash),'Live GGCON balance')}${metric('Fame',p.fame??'—','Current fame points')}${metric('Vehicles',d.vehicles?.length||0,'Tracked vehicles')}<div class="card span8"><h3 style="margin-top:0">Welcome back, ${esc(p.name||state.me.displayName)}</h3><p style="color:var(--muted);line-height:1.7">Watcher has assembled your Outpost X services into one secure command network. Everything below is tied to your Discord identity and linked SCUM account.</p><div class="grid" style="margin-top:15px">${service('taxi','🚁','Airlift Taxi','Request emergency transport and view your cooldown.',d.airlift?.ready?'READY':'COOLDOWN')}${service('events','📅','Events','Browse upcoming events and manage your RSVPs.',(d.events||[]).filter(e=>e.status==='open').length+' UPCOMING')}${service('playershops','🏪','Player Shops','Browse storefronts or manage your own shop.')}${service('lore','📖','Player Lore','Create and browse roleplay character profiles.')}${service('squads','👥','Squad Finder','Find a squad or manage your recruiting post.')}${service('history','🧾','Watcher History','Review 15 days of Watcher activity.')}${service('vehicles','🚗','Vehicles','View your linked vehicles and insurance.')}</div></div><div class="card span4"><h3>Current Status</h3><div class="list">${statusRow('Account Link',p.steamId?'Linked':'Not linked')}${statusRow('Airlift',d.airlift?.ready?'Ready':d.airlift?.nextRide?`Ready ${fmt(d.airlift.nextRide)}`:'Unknown')}${statusRow('Dirtbike',d.rental?.status||'None')}${statusRow('Player Shop',d.myShop?.shop_name||'Not created')}${statusRow('Lore Profile',d.myLore?.character_name||'Not created')}</div><button class="btn accountShortcut" onclick="go('account')">View Account & Connection Details</button></div>${recentActivityCard(d.transactions||[])}</div>`}
else if(state.section==='account')renderAccount(v,d);else if(state.section==='staff')renderStaff(v);else if(state.section==='vehicles') renderVehicles(v,d);else if(state.section==='insurance')renderInsurance(v,d);else if(state.section==='taxi')renderTaxi(v,d);else if(state.section==='rental')renderRental(v,d);else if(state.section==='shop')renderServerShop(v,d);else if(state.section==='events')renderEvents(v,d);else if(state.section==='playershops')renderPlayerShops(v,d);else if(state.section==='squads')renderSquads(v,d);else if(state.section==='lore')renderLore(v,d);else if(state.section==='history')renderHistory(v,d.transactions||[],false);else if(state.section==='admin')renderAdmin(v,d);else if(state.section==='owner'){if(!state.me.isOwner)return go('dashboard');renderOwnerControls(v)}else if(state.section==='surveillance'){if(!(state.me.isOwner||state.me.permissions?.use_surveillance))return go('dashboard');title('ADMIN SURVEILLANCE','48-Hour Movement DVR');v.innerHTML='<iframe class="surveillance" src="/tracker/view"></iframe>'}}
function statusRow(a,b){return `<div class="row"><div><b>${esc(a)}</b></div><span>${esc(b)}</span></div>`}
function recentActivityCard(rows){const items=(rows||[]).slice(0,5);return `<div class=\"card span12 recentActivity\"><div class=\"cardHeading\"><div><small>RECENT WATCHER ACTIVITY</small><h3>Your latest Command Center actions</h3></div><button class=\"btn\" onclick=\"go('history')\">View Full History</button></div><div class=\"activityList\">${items.map(x=>`<button class=\"activityRow\" onclick=\"go('history')\"><span class=\"activityIcon\">${activityIcon(x.type)}</span><div><b>${esc(x.title||x.type||'Watcher activity')}</b><small>${fmt(x.created_at)}${x.status?` • ${esc(x.status)}`:''}</small></div><strong class=\"${Number(x.amount)>=0?'pos':'neg'}\">${Number(x.amount)?money(x.amount):'VIEW'}</strong></button>`).join('')||'<div class=\"emptyState\"><i>🧾</i><b>No recent activity</b><span>Your purchases, rentals, airlifts, insurance and refunds will appear here.</span></div>'}</div></div>`}
function activityIcon(type){const t=String(type||'').toLowerCase();if(t.includes('shop'))return'🛒';if(t.includes('insurance'))return'🛡️';if(t.includes('airlift')||t.includes('taxi'))return'🚁';if(t.includes('rental'))return'🏍️';if(t.includes('refund'))return'↩️';return'👁️'}
function renderAccount(v,d){title('IDENTITY & ACCESS','Account Connection');const p=d.player||{},me=d.me||{};const linked=!!p.steamId;const role=me.isOwner?'Owner':me.isAdmin?'Admin':'The Exiles';const verified=d.system?.verifiedAt?fmt(d.system.verifiedAt):'This visit';v.innerHTML=`<div class=\"grid accountGrid\"><div class=\"card span7 accountHero\"><div class=\"accountIdentity\"><img src=\"${esc(me.avatar||'/portal/assets/watcher.jpg')}\"><div><small>DISCORD IDENTITY</small><h3>${esc(me.displayName||'Outpost Player')}</h3><span class=\"status good\">${esc(role.toUpperCase())}</span></div></div><p>Your Command Center access is granted through Discord. Watcher checks your server membership and role when you return.</p><div class=\"connectionGrid\">${connectionTile('Discord Server','Connected',true,'Membership verified')}${connectionTile('Discord Role',role,true,'Portal access granted')}${connectionTile('SCUM Account',linked?'Registered':'Not registered',linked,linked?esc(p.name||p.steamId):'Use the Discord registration flow')}${connectionTile('Secure Login','Active',true,`Rolling access through ${fmt(me.sessionExpiresAt)}`)}</div></div><div class=\"card span5\"><h3>Verification Details</h3><div class=\"list\">${statusRow('Character',p.name||'Not linked')}${statusRow('Steam64',p.steamId||'Not linked')}${statusRow('Current Status',p.online?'Online in SCUM':'Offline')}${statusRow('Last Role Check',verified)}</div>${linked?'':`<div class=\"accountWarning\"><b>Registration required</b><p>You can enter the portal with the required Discord role, but player-specific services require your Discord account to be registered to your SCUM character first.</p></div>`}</div><div class=\"card span12 securityNote\"><i>🔒</i><div><b>Watcher security</b><p>Saving or bookmarking this page does not bypass Discord registration, required roles, or SCUM account linking. Access is revalidated automatically.</p></div></div></div>`}
function connectionTile(label,value,ok,sub){return `<div class=\"connectionTile ${ok?'ok':'bad'}\"><span>${ok?'✓':'!'}</span><div><small>${esc(label)}</small><b>${esc(value)}</b><em>${esc(sub)}</em></div></div>`}
function renderStaff(v){
  title('OUTPOST X PERSONNEL','Outpost X Staff');
  const staff=[
    {name:'Josh',role:'Owner',image:'josh',tag:'Server Owner · Development · Watcher Systems',quote:'The person responsible for all of this.',owner:true},
    {name:'Nivy',role:'Admin',image:'nivy',tag:'Unicorn Queen · Community Support · Events',quote:'Bringing magic, mayhem, and just enough order to keep Outpost X alive.',magic:true},
    {name:'Cat',role:'Admin',image:'cat',tag:'Community · Player Support · Chaos Management',quote:'Helpful, suspicious, and apparently a delight.'},
    {name:'Deathbloom',role:'Admin',image:'deathbloom',tag:'Player Support · Community · Problem Solving',quote:'Calm support for questionable situations.'},
    {name:'CrazyLady',role:'Admin',image:'crazylady',tag:'New Player Support · Community · Group Mom',quote:'Keeping everyone alive, fed, and slightly insulted.'},
    {name:'OneEyedDude',role:'Admin',image:'oneeyeddude',tag:'Player Support · Technical Help · Long-Range Judgment',quote:'Watching quietly and judging from a safe distance.'},
  ];
  v.innerHTML=`<section class="staffIntro card"><div><span class="staffKicker">THE TEAM BEHIND THE WALLS</span><h3>Meet the people behind Outpost X.</h3><p>The people keeping Outpost X running, helping players, and occasionally containing or causing the chaos.</p></div><article class="watcherStaffCard"><div class="watcherScan"></div><img src="/portal/assets/staff/watcher-staff.webp" alt="The Watcher"><div class="watcherStaffCopy"><span class="status good">SYSTEM ONLINE</span><small>CUSTOM BOT · SERVER INTELLIGENCE</small><h3>The Watcher</h3><p>Automation, player services, monitoring, events, surveillance, and questionable decision support.</p></div></article></section><section class="staffGrid">${staff.map(s=>`<article class="staffCard ${s.owner?'ownerCard':''} ${s.magic?'magicCard':''}"><div class="staffPortrait"><img src="/portal/assets/staff/${s.image}.webp" alt="${esc(s.name)}"><div class="staffGlow"></div><span class="staffRole ${s.owner?'ownerRole':''}">${esc(s.role)}</span></div><div class="staffBody"><small>${esc(s.tag)}</small><h3>${esc(s.name)}</h3><p>${esc(s.quote)}</p></div></article>`).join('')}</section><section class="staffHelp card"><div><span class="staffKicker">NEED STAFF HELP?</span><h3>Use the ticket system so the right person can help.</h3><p>For account problems, vehicle issues, rule questions, shop approval, reports, or technical support, open a ticket through Discord instead of privately messaging staff.</p></div><a class="btn primary" href="https://discord.com/channels/1516269432538661025/1531709557997306027" target="_blank" rel="noopener">Open Discord</a></section>`;
}
const FALLBACK_PORTAL_MAP={width:2048,height:2048,uX:-0.00134396890,uY:0.0000000676414083,u0:831.454665,vX:-0.00000000142817301,vY:-0.00134384750,v0:831.522683};
function portalMap(){return state.data?.mapCalibration||FALLBACK_PORTAL_MAP}
const SECTOR_ROWS=['D','C','B','A','Z'],SECTOR_COLS=['4','3','2','1','0'];

const mapZoomStates=new Map();
const PORTAL_TILE_CONFIG={baseDimension:2048,highDimension:14481,highTileSize:2048,highColumns:8,highRows:8,switchZoom:2.15,maxZoom:9};
function tileMapMarkup(id,leftPct,topPct,startZoom=3.2,kind='vehicle'){
  return `<div class="tileMapViewport zoomableMap" id="${id}" data-focus-x="${leftPct}" data-focus-y="${topPct}" data-start-zoom="${startZoom}"><div class="tileMapBase"></div><div class="tileMapTiles"></div><span class="precisionMarker ${kind==='event'?'eventMarker':'vehicleMarker'}" aria-label="Exact recorded location"><span></span></span>${mapZoomControls(id)}<div class="mapZoomHint">Scroll or use +/− to zoom • drag to move</div></div>`;
}
function initZoomableMap(id){
  const viewport=$(id);if(!viewport)return;
  const tiles=viewport.querySelector('.tileMapTiles'),base=viewport.querySelector('.tileMapBase'),marker=viewport.querySelector('.precisionMarker');if(!tiles||!base||!marker)return;
  const focusX=Math.max(0,Math.min(1,Number(viewport.dataset.focusX||50)/100)),focusY=Math.max(0,Math.min(1,Number(viewport.dataset.focusY||50)/100));
  const startZoom=Math.max(1,Math.min(PORTAL_TILE_CONFIG.maxZoom,Number(viewport.dataset.startZoom||1)));
  const st={zoom:startZoom,panX:0,panY:0,focusX,focusY,drag:null,lastLevel:'',tileKeys:new Set()};mapZoomStates.set(id,st);
  const clamp=()=>{const r=viewport.getBoundingClientRect(),mx=r.width*(st.zoom-1)/2,my=r.height*(st.zoom-1)/2;st.panX=Math.max(-mx,Math.min(mx,st.panX));st.panY=Math.max(-my,Math.min(my,st.panY))};
  const screen=(nx,ny,r)=>({x:(nx-.5)*r.width*st.zoom+r.width/2+st.panX,y:(ny-.5)*r.height*st.zoom+r.height/2+st.panY});
  const renderTiles=()=>{
    const r=viewport.getBoundingClientRect();if(!r.width||!r.height)return;
    base.style.transform=`translate(${st.panX}px,${st.panY}px) scale(${st.zoom})`;
    const mp=screen(st.focusX,st.focusY,r);marker.style.left=`${mp.x}px`;marker.style.top=`${mp.y}px`;
    const useHi=st.zoom>=PORTAL_TILE_CONFIG.switchZoom;
    tiles.style.display=useHi?'block':'none';base.style.display=useHi?'none':'block';
    if(useHi){
      const dim=PORTAL_TILE_CONFIG.highDimension,tile=PORTAL_TILE_CONFIG.highTileSize;
      const leftN=Math.max(0,.5-(r.width/2+st.panX)/(r.width*st.zoom)),rightN=Math.min(1,.5+(r.width/2-st.panX)/(r.width*st.zoom));
      const topN=Math.max(0,.5-(r.height/2+st.panY)/(r.height*st.zoom)),bottomN=Math.min(1,.5+(r.height/2-st.panY)/(r.height*st.zoom));
      const x0=Math.max(0,Math.floor(leftN*dim/tile)),x1=Math.min(PORTAL_TILE_CONFIG.highColumns-1,Math.floor(rightN*dim/tile));
      const y0=Math.max(0,Math.floor(topN*dim/tile)),y1=Math.min(PORTAL_TILE_CONFIG.highRows-1,Math.floor(bottomN*dim/tile));
      const needed=new Set();
      for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){
        const key=`${x}_${y}`;needed.add(key);let img=tiles.querySelector(`[data-tile="${key}"]`);
        if(!img){img=document.createElement('img');img.dataset.tile=key;img.alt='';img.draggable=false;img.src=`/tracker/tiles/hi/${key}.jpg`;tiles.appendChild(img)}
        const nx=(x*tile)/dim,ny=(y*tile)/dim,nw=Math.min(tile,dim-x*tile)/dim,nh=Math.min(tile,dim-y*tile)/dim;
        const a=screen(nx,ny,r),b=screen(nx+nw,ny+nh,r);img.style.left=`${a.x}px`;img.style.top=`${a.y}px`;img.style.width=`${b.x-a.x+1}px`;img.style.height=`${b.y-a.y+1}px`;img.style.display='block';
      }
      tiles.querySelectorAll('img').forEach(img=>{if(!needed.has(img.dataset.tile))img.style.display='none'});
    }
    const z=viewport.querySelector('[data-map-zoom-label]');if(z)z.textContent=`${Math.round(st.zoom*100)}%`;
  };
  st.render=renderTiles;st.clamp=clamp;
  const centerFocus=()=>{const r=viewport.getBoundingClientRect();st.panX=(.5-st.focusX)*r.width*st.zoom;st.panY=(.5-st.focusY)*r.height*st.zoom;clamp();renderTiles()};
  viewport.addEventListener('wheel',e=>{e.preventDefault();const r=viewport.getBoundingClientRect(),old=st.zoom,next=Math.max(1,Math.min(PORTAL_TILE_CONFIG.maxZoom,old*(e.deltaY<0?1.22:1/1.22)));if(next===old)return;const px=e.clientX-r.left-r.width/2,py=e.clientY-r.top-r.height/2,ratio=next/old;st.panX=px-(px-st.panX)*ratio;st.panY=py-(py-st.panY)*ratio;st.zoom=next;clamp();renderTiles()},{passive:false});
  viewport.addEventListener('pointerdown',e=>{if(e.target.closest('.mapZoomControls'))return;viewport.setPointerCapture(e.pointerId);st.drag={x:e.clientX,y:e.clientY,ox:st.panX,oy:st.panY};viewport.classList.add('dragging')});
  viewport.addEventListener('pointermove',e=>{if(!st.drag)return;st.panX=st.drag.ox+(e.clientX-st.drag.x);st.panY=st.drag.oy+(e.clientY-st.drag.y);clamp();renderTiles()});
  const end=()=>{st.drag=null;viewport.classList.remove('dragging')};viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);
  new ResizeObserver(()=>renderTiles()).observe(viewport);centerFocus();
}
function zoomPortalMap(id,dir){const st=mapZoomStates.get(id);if(!st)return;st.zoom=Math.max(1,Math.min(PORTAL_TILE_CONFIG.maxZoom,st.zoom*(dir>0?1.28:1/1.28)));if(st.zoom===1){st.panX=0;st.panY=0}st.clamp();st.render()}
function resetPortalMap(id){const viewport=$(id),st=mapZoomStates.get(id);if(!viewport||!st)return;st.zoom=Math.max(1,Math.min(PORTAL_TILE_CONFIG.maxZoom,Number(viewport.dataset.startZoom||1)));const r=viewport.getBoundingClientRect();st.panX=(.5-st.focusX)*r.width*st.zoom;st.panY=(.5-st.focusY)*r.height*st.zoom;st.clamp();st.render()}
function mapZoomControls(id){return `<div class="mapZoomControls"><button class="mapZoomBtn" type="button" onclick="event.stopPropagation();zoomPortalMap('${id}',-1)" aria-label="Zoom out">−</button><span data-map-zoom-label>100%</span><button class="mapZoomBtn" type="button" onclick="event.stopPropagation();zoomPortalMap('${id}',1)" aria-label="Zoom in">+</button><button class="mapZoomBtn reset" type="button" onclick="event.stopPropagation();resetPortalMap('${id}')">Reset</button></div>`}

function vehicleCoords(x){const candidates=[x?.location,x?.lastLocation,x?.position,x];for(const l of candidates){if(!l||typeof l==='string')continue;const vx=Number(l.x??l.X),vy=Number(l.y??l.Y),vz=Number(l.z??l.Z??0);if(Number.isFinite(vx)&&Number.isFinite(vy))return{x:vx,y:vy,z:Number.isFinite(vz)?vz:0}}return null}
function mapPoint(x,y){const m=portalMap();return{x:m.uX*x+m.uY*y+m.u0,y:m.vX*x+m.vY*y+m.v0}}
function sectorForPoint(q){const m=portalMap(),col=Math.max(0,Math.min(4,Math.floor((q.x/m.width)*5))),row=Math.max(0,Math.min(4,Math.floor((q.y/m.height)*5)));return`${SECTOR_ROWS[row]}${SECTOR_COLS[col]}`}
function vehicleLocation(x){const c=vehicleCoords(x);if(typeof x?.sector==='string'&&x.sector)return x.sector;if(c){const q=mapPoint(c.x,c.y);return `Sector ${sectorForPoint(q)} • X ${Math.round(c.x)} • Y ${Math.round(c.y)} • Z ${Math.round(c.z)}`}const l=x?.location;if(typeof l==='string'&&l)return l;return 'Location unavailable'}
function renderVehicles(v,d){title('PLAYER ASSETS','Vehicles');const rows=(d.vehicles||[]).map((x,i)=>{const c=vehicleCoords(x);return `<button type="button" class="row vehicleRow${c?' clickable':''}" ${c?`onclick="openVehicleMap(${i})"`:''}><div><b>${esc(x.name||x.vehicleName||x.class||'Vehicle')}</b><small>ID ${esc(x.id||x.vehicleId||'Unknown')} • ${esc(vehicleLocation(x))}${x.squadName?` • ${esc(x.squadName)}`:''}${x.lastActive?` • Last used ${esc(fmt(x.lastActive))}`:' • Last used not yet reported'}</small>${c?'<em>Click to view this vehicle on the map</em>':''}</div><div class="vehicleRowEnd"><span class="status">${esc(x.insured?'INSURED':'UNINSURED')}</span>${c?'<span class="mapArrow">OPEN MAP →</span>':''}</div></button>`}).join('');v.innerHTML=`<div class="card"><div class="list">${rows||'<div class="emptyState"><i>🚗</i><b>No vehicles found</b><span>Watcher did not find vehicles linked to your character or squad.</span></div>'}</div></div>`}
function openVehicleMap(index){const x=state.data?.vehicles?.[Number(index)],c=vehicleCoords(x);if(!x||!c)return toast('This vehicle does not have a usable recorded location.');const q=mapPoint(c.x,c.y),m=portalMap(),left=Math.max(0,Math.min(100,(q.x/m.width)*100)),top=Math.max(0,Math.min(100,(q.y/m.height)*100)),sector=sectorForPoint(q),name=x.name||x.vehicleName||x.class||'Vehicle',mapId='vehicleMapViewport';openDetailModal(`<div class="detailHero"><div><span class="eyebrow">WATCHER VEHICLE LOCATION</span><h2>${esc(name)}</h2><p>Vehicle ID ${esc(x.id||x.vehicleId||'Unknown')}${x.squadName?` • ${esc(x.squadName)}`:''}</p></div><span class="status ${x.insured?'good':''}">${x.insured?'INSURED':'UNINSURED'}</span></div><section class="vehicleLocationPanel"><div class="eventMapHeader"><div><span class="eyebrow">LAST REPORTED POSITION</span><h3>Sector ${esc(sector)}</h3></div><span class="coordBadge">X ${Math.round(c.x)} • Y ${Math.round(c.y)} • Z ${Math.round(c.z)}</span></div>${tileMapMarkup(mapId,left.toFixed(5),top.toFixed(5),4.2,'vehicle')}<div class="vehicleMapFoot"><span>Map position is based on Watcher’s latest GGCON vehicle location.</span><button class="btn" onclick="navigator.clipboard.writeText('#Teleport ${c.x.toFixed(3)} ${c.y.toFixed(3)} ${c.z.toFixed(3)}').then(()=>toast('Teleport coordinates copied.'))">Copy Coordinates</button></div></section>`);setTimeout(()=>initZoomableMap(mapId),0)}
function renderInsurance(v,d){title('ASSET PROTECTION','Vehicle Insurance');v.innerHTML='<div class="card"><div class="empty">Loading insurance controls…</div></div>';api('/portal/api/insurance/options').then(o=>{const policies=(o.policies||[]).map(x=>`<div class="row"><div><b>${esc(x.vehicle_name||x.vehicle_type||'Vehicle policy')}</b><small>Vehicle ${esc(x.vehicle_id||'—')} • Purchased ${fmt(x.purchased_at)}</small></div><span class="status good">${esc((x.status||'active').toUpperCase())}</span></div>`).join('');const eligible=(o.vehicles||[]).filter(x=>x.eligible).map(x=>`<div class="row insuranceOption"><div class="insuranceVehicle"><b>${esc(x.label||x.name)}</b><small>Vehicle ID ${esc(x.id)}</small></div><div class="insurancePurchase"><div class="insurancePrice"><small>INSURANCE COST</small><strong>${money(x.price)}</strong></div><button class="btn primary insuranceBuyBtn" onclick="buyInsurance('${esc(x.id)}')">Insure for ${money(x.price)}</button></div></div>`).join('');const claims=(o.claims||[]).map(x=>`<div class="row"><div><b>${esc(x.policy?.vehicle_name||x.vehicle_name||'Replacement Vehicle')}</b><small>Destroyed vehicle ${esc(x.vehicle_id||'—')}</small></div><button class="btn primary" onclick="redeemInsurance('${esc(x.id)}')">Redeem</button></div>`).join('');v.innerHTML=`<div class="grid"><div class="card span6"><h3>Active Policies</h3><div class="list">${policies||'<div class="empty">No active policies.</div>'}</div></div><div class="card span6"><h3>Available Claims</h3><div class="list">${claims||'<div class="empty">No replacement claims are available.</div>'}</div></div><div class="card span12"><h3>Eligible Vehicles</h3><div class="list">${eligible||'<div class="empty">No eligible uninsured vehicles were found.</div>'}</div></div></div>`}).catch(e=>v.innerHTML=`<div class="card empty">${esc(e.message)}</div>`)}
async function buyInsurance(vehicleId){if(!confirm('Purchase insurance for this vehicle?'))return;try{const r=await api('/portal/api/insurance/buy',{method:'POST',body:JSON.stringify({vehicleId})});toast('Insurance activated.');await refresh();render()}catch(e){toast(e.message)}}
async function redeemInsurance(claimId){if(!confirm('Redeem this insurance claim and spawn the replacement vehicle?'))return;try{await api('/portal/api/insurance/redeem',{method:'POST',body:JSON.stringify({claimId})});toast('Replacement vehicle spawned.');await refresh();render()}catch(e){toast(e.message)}}
function renderTaxi(v,d){
  title('EMERGENCY TRANSPORT','Airlift Taxi');
  const sectors=SECTOR_ROWS.flatMap(row=>SECTOR_COLS.map(col=>`${row}${col}`));
  const selected=state.taxiSector&&state.taxiSector!=='C0'?state.taxiSector:null;
  v.innerHTML=`<div class="grid taxiLayout"><div class="card span8 taxiMapCard"><div class="taxiIntro"><div><h3>Choose Your Destination</h3><p>Airlift cost: <b>${money(1000)}</b>. Select a sector directly on the map, then confirm your ride.</p></div><span class="status ${d.airlift?.ready?'good':'bad'}">${d.airlift?.ready?'READY':'COOLDOWN'}</span></div><div class="taxiMapShell"><img src="/tracker/map.png" alt="SCUM sector map for choosing an Airlift Taxi destination" draggable="false"><div class="taxiSectorGrid">${sectors.map(sector=>`<button type="button" class="taxiSectorCell${selected===sector?' selected':''}${sector==='C0'?' unavailable':''}" data-sector="${sector}" aria-label="${sector==='C0'?'Sector C0 unavailable':'Select sector '+sector}" ${sector==='C0'?'disabled':''} onclick="selectTaxiSector('${sector}')"><span>${sector==='C0'?'UNAVAILABLE':sector}</span></button>`).join('')}</div><div class="taxiMapInstruction">Click a sector on the map</div></div></div><div class="card span4 taxiStatusCard"><h3>Ride Status</h3>${statusRow('Availability',d.airlift?.ready?'READY':'COOLDOWN')}${statusRow('Next Ride',d.airlift?.ready?'Now':fmt(d.airlift?.nextRide))}<div id="taxiSelectionPanel" class="taxiSelectionPanel">${taxiSelectionMarkup(selected,d)}</div><p class="taxiSafety">Do not jump during the airlift sequence. Watcher will position you above the selected sector.</p></div></div>`
}
function taxiSelectionMarkup(sector,d){
  if(!sector)return `<div class="taxiEmptySelection"><b>No destination selected</b><span>Choose a sector from the map.</span></div>`;
  const ready=!!d?.airlift?.ready;
  if(state.taxiPrepared?.sector===sector)return `<div class="taxiSelectedSector prepared"><small>PARACHUTE DELIVERED</small><strong>Sector ${sector}</strong><span>Put on the parachute now. Do not jump or move until Watcher launches you.</span></div><button class="btn primary taxiConfirm" onclick="sendTaxi('${sector}')">🚁 I’m Ready — Send Airlift</button><button class="btn taxiClear" onclick="cancelTaxi()">Cancel Without Charge</button>`;
  return `<div class="taxiSelectedSector"><small>SELECTED DESTINATION</small><strong>Sector ${sector}</strong><span>Step 1 of 2: Watcher will deliver a parachute. You will not be charged or teleported yet.</span></div><button class="btn primary taxiConfirm" ${ready?'':'disabled'} onclick="prepareTaxi('${sector}')">🪂 Prepare Airlift to ${sector}</button><button class="btn taxiClear" onclick="clearTaxiSector()">Clear Selection</button>`
}
function selectTaxiSector(sector){
  if(!sector||sector==='C0')return;
  state.taxiSector=sector;state.taxiPrepared=null;
  document.querySelectorAll('.taxiSectorCell').forEach(cell=>cell.classList.toggle('selected',cell.dataset.sector===sector));
  const panel=$('taxiSelectionPanel');if(panel)panel.innerHTML=taxiSelectionMarkup(sector,state.data);
}
function clearTaxiSector(){state.taxiSector=null;state.taxiPrepared=null;document.querySelectorAll('.taxiSectorCell').forEach(cell=>cell.classList.remove('selected'));const panel=$('taxiSelectionPanel');if(panel)panel.innerHTML=taxiSelectionMarkup(null,state.data)}
async function prepareTaxi(sector){
  if(!confirm(`Prepare an airlift to sector ${sector}? Watcher will spawn a parachute, but you will not be charged or teleported yet.`))return;
  try{
    const r=await api('/portal/api/action/taxi/prepare',{method:'POST',body:JSON.stringify({sector})});
    state.taxiPrepared={sector:r.sector,expiresAt:r.expiresAt};
    const panel=$('taxiSelectionPanel');if(panel)panel.innerHTML=taxiSelectionMarkup(sector,state.data);
    toast('Parachute delivered. Put it on, then press Send Airlift.');
  }catch(e){toast(e.message)}
}
async function sendTaxi(sector){
  if(!confirm(`Are you wearing the parachute and ready to launch to sector ${sector}? After confirming, Watcher will wait 10 seconds so you can return to SCUM. You will be charged $1,000 immediately before teleport.`))return;
  const panel=$('taxiSelectionPanel');
  let remaining=10;
  if(panel)panel.innerHTML=`<div class="taxiSelectedSector prepared launching"><small>AIRLIFT LAUNCH SEQUENCE</small><strong>Sector ${sector}</strong><span>Return to the SCUM game window now. Launching in <b id="taxiCountdown">${remaining}</b> seconds…</span></div><button class="btn primary taxiConfirm" disabled>🚁 Launch Sequence Active</button>`;
  const timer=setInterval(()=>{remaining=Math.max(0,remaining-1);const el=$('taxiCountdown');if(el)el.textContent=remaining;},1000);
  try{
    await api('/portal/api/action/taxi/send',{method:'POST',body:JSON.stringify({sector})});
    clearInterval(timer);
    state.taxiPrepared=null;state.taxiSector=null;
    toast(`Airlift launched to ${sector}. Deploy your parachute and land safely.`);
    await refresh();render();
  }catch(e){
    clearInterval(timer);
    toast(e.message);
    const panelNow=$('taxiSelectionPanel');if(panelNow)panelNow.innerHTML=taxiSelectionMarkup(sector,state.data);
  }
}
async function cancelTaxi(){
  try{await api('/portal/api/action/taxi/cancel',{method:'POST',body:'{}'});}catch{}
  state.taxiPrepared=null;clearTaxiSector();toast('Airlift cancelled. You were not charged.');
}
function renderRental(v,d){title('TEMPORARY TRANSPORT','Dirtbike Rental');const r=d.rental||{};v.innerHTML=`<div class="grid"><div class="card span8"><h3>30-Minute Dirtbike Rental</h3><p style="color:var(--muted)">Cost: <b>${money(500)}</b>. Watcher spawns a tracked dirtbike for 30 minutes and removes it automatically when time expires.</p><button class="btn primary" onclick="requestRental()" ${r.status==='active'?'disabled':''}>${r.status==='active'?'Rental Active':'Rent Dirtbike'}</button></div><div class="card span4"><h3>Rental Status</h3>${statusRow('Status',r.status||'None')}${statusRow('Vehicle ID',r.vehicle_id||'—')}${statusRow('Expires',fmt(r.expires_at))}</div></div>`}
async function requestRental(){if(!confirm('Rent a dirtbike for $500?'))return;try{await api('/portal/api/action/rental',{method:'POST',body:'{}'});toast('Dirtbike rental started.');await refresh()}catch(e){toast(e.message)}}
function renderServerShop(v,d){
  title('WATCHER SUPPLY NETWORK','Server Shop');
  const canManage=state.me?.isOwner||state.me?.permissions?.manage_server_shop;
  const canEdit=state.me?.isOwner||state.me?.permissions?.edit_shop_products;
  const products=d.shopCatalog||[];
  const categories=[...new Set(products.map(x=>String(x.category||'General').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const manager=canManage?`<div class="card span12 manageHero"><div><small>${state.me?.isOwner?'OWNER EYES ONLY':'AUTHORIZED SHOP CONTROL'}</small><h2>Server Shop Manager</h2><p>Edit products, prices, quantities, package contents, ordering, and availability from the visual inventory manager.</p></div><button class="btn primary" onclick="openServerShopManagerFromStore()">Manage Server Shop</button></div>`:'';
  const categoryFilter=categories.length>1?`<div class="card span12 shopCategoryBar"><label>Category<select id="serverShopCategory" onchange="filterServerShopCategory(this.value)"><option value="all">All Categories</option>${categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label></div>`:'';
  v.innerHTML=`<div class="grid">${manager}${categoryFilter}<div class="span12 shopProductGrid" id="serverShopProducts">${products.map(x=>`<div class="card shopproduct" data-shop-category="${esc(String(x.category||'General'))}"><div style="font-size:34px">${esc(x.emoji||'📦')}</div><h3>${esc(x.name)}</h3><p style="color:var(--muted);min-height:42px">${esc(x.description||'Emergency supply package')}</p><small class="shopCategoryLabel">${esc(x.category||'General')}</small><div class="list" style="margin:12px 0">${(x.contents||[]).map(i=>`<div class="row"><span>${esc(i.label)}</span><b>×${Number(i.qty||1)}</b></div>`).join('')}</div><b style="font-size:24px">${money(x.price)}</b><div class="adminActions" style="margin-top:14px"><button class="btn primary" onclick="buyItem('${esc(x.id)}','${esc(x.name)}',${Number(x.price||0)})">Purchase & Deliver</button>${canEdit?`<button class="btn" onclick="editServerShopProductFromStore('${esc(x.id)}')">Edit Product</button>`:''}</div></div>`).join('')||'<div class="card empty">No server-shop packages are configured.</div>'}</div></div>`
}
function filterServerShopCategory(category){document.querySelectorAll('#serverShopProducts [data-shop-category]').forEach(card=>card.style.display=category==='all'||card.dataset.shopCategory===category?'':'none')}
function openServerShopManagerFromStore(){
  if(!(state.me?.isOwner||state.me?.permissions?.manage_server_shop))return toast('You do not have permission to manage the Server Shop.');
  go('admin');
  setTimeout(()=>adminTab('serverShop'),0);
}
async function editServerShopProductFromStore(id){
  if(!(state.me?.isOwner||state.me?.permissions?.edit_shop_products))return toast('You do not have permission to edit Server Shop products.');
  try{
    const r=await api('/portal/api/admin/shop/products');
    shopManagerProducts=r.products||[];
    const product=shopManagerProducts.find(x=>String(x.id)===String(id)||String(x.slug)===String(id));
    if(!product)throw new Error('That product could not be found in the managed catalogue.');
    openShopProductEditor(product.id);
  }catch(e){toast(e.message)}
}
async function buyItem(id,name,price){if(!confirm(`Purchase ${name} for ${money(price)}? You must be online in SCUM.`))return;$('modalBody').innerHTML=`<h2>Delivering ${esc(name)}</h2><div class="deliveryStages"><div class="deliveryStage active" id="stageOnline">1. Verifying you are online in SCUM</div><div class="deliveryStage" id="stagePayment">2. Authorizing payment</div><div class="deliveryStage" id="stageDelivery">3. Sending items through GGCON</div><div class="deliveryStage" id="stageConfirmed">4. Waiting for confirmed delivery</div></div><p id="deliveryMessage">Do not close this window or click purchase again.</p>`;$('modal').classList.remove('hidden');try{await new Promise(r=>setTimeout(r,250));$('stageOnline').className='deliveryStage done';$('stagePayment').className='deliveryStage active';const pending=setTimeout(()=>{$('stagePayment').className='deliveryStage done';$('stageDelivery').className='deliveryStage active';},700);const requestId=(crypto?.randomUUID?.()||`shop-${Date.now()}-${Math.random().toString(16).slice(2)}`);const r=await api('/portal/api/action/shop',{method:'POST',headers:{'X-Idempotency-Key':requestId},body:JSON.stringify({id,requestId})});clearTimeout(pending);$('stagePayment').className='deliveryStage done';$('stageDelivery').className='deliveryStage done';$('stageConfirmed').className='deliveryStage done';$('deliveryMessage').textContent=`Confirmed delivered near ${r.playerName||'your character'}.`;toast(`${r.package?.name||name} delivered near ${r.playerName||'your character'}.`,'good');setTimeout(()=>closeModal(),1200);await refresh()}catch(e){document.querySelectorAll('.deliveryStage.active').forEach(x=>x.classList.add('bad'));$('deliveryMessage').textContent=e.message;toast(e.message)}}
function renderCollection(v,eye,t,items,card){title(eye,t);v.innerHTML=`<div class="searchbar"><input id="filter" placeholder="Search ${t.toLowerCase()}" oninput="filterCards()"></div><div class="grid" id="cards">${items.map(card).join('')||'<div class="card span12 empty">Nothing has been published yet.</div>'}</div>`}
function filterCards(){const q=$('filter').value.toLowerCase();document.querySelectorAll('#cards>[data-search]').forEach(e=>e.style.display=e.dataset.search.includes(q)?'block':'none')}
function imageStrip(urls){const a=Array.isArray(urls)?urls.filter(Boolean):[];return a.length?`<div class="imageStrip">${a.map(u=>`<img src="${esc(u)}" loading="lazy">`).join('')}</div>`:''}
function shopCard(x){return `<button type="button" class="card span4 directoryCard" data-search="${esc(`${x.shop_name} ${x.owner_name||''} ${x.shop_type} ${x.location_text||''}`.toLowerCase())}" onclick="openShopDetail('${esc(x.id)}')">${imageStrip(x.image_urls)}<div class="directoryTop"><span class="status ${x.is_open?'good':''}">${x.is_open?'OPEN':'CLOSED'}</span><span class="openHint">OPEN PROFILE ›</span></div><h3>${esc(x.shop_name||'Player Shop')}</h3><p>${esc(shortText(x.description||'No description',150))}</p><small>${esc(x.location_text||'Location hidden')} • ${esc(x.shop_type||'General')}</small></button>`}
function squadCard(x){return `<button type="button" class="card span4 directoryCard" data-search="${esc(`${x.squad_name} ${x.play_style} ${x.active_times}`.toLowerCase())}" onclick="openSquadDetail('${esc(x.id)}')"><div class="directoryTop"><span class="status ${x.is_recruiting?'good':''}">${x.is_recruiting?'RECRUITING':'CLOSED'}</span><span class="openHint">OPEN LISTING ›</span></div><h3>${esc(x.squad_name||'Squad')}</h3><p>${esc(shortText(x.description||'No description',150))}</p><div class="list compact">${statusRow('Members',x.member_count||'Not listed')}${statusRow('Style',x.play_style||'Any')}${statusRow('Active',x.active_times||'Any time')}</div></button>`}
function loreCard(x){return `<button type="button" class="card span4 directoryCard" data-search="${esc(`${x.character_name} ${x.category} ${x.faction_squad||''} ${x.origin}`.toLowerCase())}" onclick="openLoreDetail('${esc(x.id)}')">${imageStrip(x.image_urls)}<div class="directoryTop"><span class="status good">${esc(x.rp_status||'RP')}</span><span class="openHint">READ FULL LORE ›</span></div><h3>${esc(x.character_name||'Unknown Survivor')}</h3><p>${esc(shortText(x.backstory||x.personality||'No lore summary',150))}</p><small>${esc(x.category||'Survivor')} • ${esc(x.faction_squad||'Unaffiliated')}</small></button>`}
function shortText(value,max=160){const t=String(value||'').replace(/\s+/g,' ').trim();return t.length>max?t.slice(0,max-1)+'…':t}
function fullText(value,fallback='Not provided'){const t=String(value||'').trim();return t?esc(t).replace(/\n/g,'<br>'):`<span class="mutedText">${esc(fallback)}</span>`}
function detailImages(urls,caption=''){const a=Array.isArray(urls)?urls.filter(Boolean):[];if(!a.length)return'';return `<div class="detailGallery">${a.map((u,i)=>`<button type="button" onclick="openImageViewer('${esc(u)}')"><img src="${esc(u)}" alt="Image ${i+1}"></button>`).join('')}</div>${caption?`<div class="imageCaption">${fullText(caption,'')}</div>`:''}`}
function detailField(label,value,fallback='Not provided'){return `<div class="detailField"><small>${esc(label)}</small><div>${fullText(value,fallback)}</div></div>`}
function openDetailModal(html){const modal=$('modal').querySelector('.modal');modal.classList.add('detailModal');$('modalBody').innerHTML=html;$('modal').classList.remove('hidden')}
function openShopDetail(id){const x=(state.data?.shops||[]).find(v=>String(v.id)===String(id))||(String(state.data?.myShop?.id)===String(id)?state.data.myShop:null);if(!x)return toast('That shop is no longer available.');openDetailModal(`<div class="detailHero"><div><span class="eyebrow">PLAYER MARKETPLACE</span><h2>${esc(x.shop_name||'Player Shop')}</h2><p>${esc(x.owner_name?`Operated by ${x.owner_name}`:'Player-owned storefront')}</p></div><span class="status ${x.is_open?'good':''}">${x.is_open?'OPEN':'CLOSED'}</span></div>${detailImages(x.image_urls,x.storefront_text)}<div class="detailGrid">${detailField('Shop Type',x.shop_type,'General')}${detailField('Location / Sector',x.location_text,'Location not listed')}${detailField('Owner',x.owner_name||x.owner_display_name,'Not listed')}${detailField('Last Updated',x.updated_at?fmt(x.updated_at):'Not available')}</div><section class="detailSection"><h3>About This Shop</h3><div class="longText">${fullText(x.description,'No shop description has been added.')}</div></section>`)}
function openSquadDetail(id){const x=(state.data?.squads||[]).find(v=>String(v.id)===String(id))||(String(state.data?.mySquad?.id)===String(id)?state.data.mySquad:null);if(!x)return toast('That squad listing is no longer available.');openDetailModal(`<div class="detailHero"><div><span class="eyebrow">SQUAD NETWORK</span><h2>${esc(x.squad_name||'Squad')}</h2><p>${esc(x.owner_name?`Listed by ${x.owner_name}`:'Outpost X squad listing')}</p></div><span class="status ${x.is_recruiting?'good':''}">${x.is_recruiting?'RECRUITING':'NOT RECRUITING'}</span></div><div class="detailGrid">${detailField('Members',x.member_count,'Not listed')}${detailField('Play Style',x.play_style,'Any')}${detailField('Active Times',x.active_times,'Any time')}${detailField('Voice Chat',x.voice_chat,'Optional')}${detailField('Leader / Contact',x.owner_name||x.owner_display_name,'Listing owner')}${detailField('Last Updated',x.updated_at?fmt(x.updated_at):'Not available')}</div><section class="detailSection"><h3>Squad Description</h3><div class="longText">${fullText(x.description,'No squad description has been added.')}</div></section>`)}
function openLoreDetail(id){const all=[...(state.data?.lore||[])];if(state.data?.myLore&&!all.some(v=>String(v.id)===String(state.data.myLore.id)))all.push(state.data.myLore);const x=all.find(v=>String(v.id)===String(id));if(!x)return toast('That lore profile is no longer available.');openDetailModal(`<div class="detailHero"><div><span class="eyebrow">ROLEPLAY ARCHIVE</span><h2>${esc(x.character_name||'Unknown Survivor')}</h2><p>${esc(x.title_nickname||x.category||'Outpost X Character')}</p></div><span class="status good">${esc(x.rp_status||'RP')}</span></div>${detailImages(x.image_urls,x.image_caption)}<div class="detailGrid">${detailField('Category',x.category,'Survivor')}${detailField('Origin',x.origin)}${detailField('Faction / Squad',x.faction_squad,'Unaffiliated')}${detailField('RP Status',x.rp_status,'Casual RP')}${detailField('Title / Nickname',x.title_nickname)}${detailField('Last Updated',x.updated_at?fmt(x.updated_at):'Not available')}</div><section class="detailSection"><h3>Backstory</h3><div class="longText">${fullText(x.backstory,'No backstory has been added.')}</div></section><section class="detailSection"><h3>Personality</h3><div class="longText">${fullText(x.personality,'No personality details have been added.')}</div></section><section class="detailSection"><h3>Goals & Motives</h3><div class="longText">${fullText(x.goals,'No goals or motives have been added.')}</div></section><section class="detailSection"><h3>Additional Lore</h3><div class="longText">${fullText(x.extra_lore,'No additional lore has been added.')}</div></section>`)}
