function renderPlayerShops(v,d){title('PLAYER MARKETPLACE','Player Shops');const mine=d.myShop;const controls=mine?manageBar(mine.shop_name,mine.is_open?'Your storefront is open.':'Your storefront is closed.',`<button class="btn primary" onclick="openShopForm()">Edit Shop</button><button class="btn" onclick="openShopImages()">Manage Images</button><button class="btn" onclick="shopAction('toggle')">${mine.is_open?'Close':'Open'} Shop</button><button class="btn dangerBtn" onclick="shopAction('delete')">Delete Shop</button>`):manageBar('Create Your Storefront','A Shop Owner role is required. Trading still happens in SCUM.',`<button class="btn primary" onclick="openShopForm()">Create Shop</button>`);v.innerHTML=`<div class="grid">${controls}<div class="card span12"><div class="searchbar"><input id="filter" placeholder="Search shops" oninput="filterCards()"></div><div class="grid" id="cards">${(d.shops||[]).map(shopCard).join('')||'<div class="empty">No shops yet.</div>'}</div></div></div>`}
function openShopForm(){const x=state.data.myShop||{};const imageCount=Array.isArray(x.image_urls)?x.image_urls.length:0;$('modalBody').innerHTML=`<h2>${x.id?'Edit':'Create'} Player Shop</h2><div class="formgrid"><label>Shop Name<input id="fShopName" maxlength="80" value="${esc(x.shop_name||'')}"></label><label>Location / Sector<input id="fShopLocation" maxlength="100" value="${esc(x.location_text||'')}"></label><label>Shop Type<input id="fShopType" maxlength="80" value="${esc(x.shop_type||'General')}"></label><label class="full">Description<textarea id="fShopDesc" rows="5">${esc(x.description||'')}</textarea></label><label class="full">Text Below Images<textarea id="fShopText" rows="4">${esc(x.storefront_text||'')}</textarea></label><label class="full">Storefront Images <small>(up to 2)</small><input id="fShopImages" type="file" accept="image/*" multiple></label>${imageCount?`<label class="checkline full"><input id="fShopRemoveImages" type="checkbox"> Remove ${imageCount} current shop image${imageCount===1?'':'s'}</label>`:''}</div><button class="btn primary" onclick="saveShop()">Save Storefront</button>`;$('modal').classList.remove('hidden');restoreDraft('playerShop');armDraft('playerShop')}
async function saveShop(){const body={shop_name:$('fShopName').value,location_text:$('fShopLocation').value,shop_type:$('fShopType').value,description:$('fShopDesc').value,storefront_text:$('fShopText').value};try{await api(`/portal/api/player-shop/${state.data.myShop?'update':'create'}`,{method:'POST',body:JSON.stringify(body)});const removeImages=$('fShopRemoveImages')?.checked===true;const hasNewImages=Boolean($('fShopImages')?.files?.length);if(removeImages||hasNewImages){const images=hasNewImages?await filesToData($('fShopImages'),2):[];await api('/portal/api/player-shop/images',{method:'POST',body:JSON.stringify({images,storefront_text:body.storefront_text})});}closeModal();clearDraft('playerShop');toast('Shop saved.');await refresh()}catch(e){toast(e.message)}}
