async function filesToData(input,maxFiles=5){const files=[...(input?.files||[])].slice(0,Math.max(1,Number(maxFiles||5)));return Promise.all(files.map(f=>new Promise((resolve,reject)=>{if(f.size>8*1024*1024)return reject(new Error(`${f.name} is larger than 8 MB.`));const r=new FileReader();r.onload=()=>resolve({name:f.name,data:r.result});r.onerror=()=>reject(new Error(`Could not read ${f.name}.`));r.readAsDataURL(f)})))}
async function saveShopImages(){try{const images=await filesToData($('shopFiles'),2);await api('/portal/api/player-shop/images',{method:'POST',body:JSON.stringify({images,storefront_text:$('shopCaption').value})});closeModal();clearDraft('playerShopImages');toast('Shop images updated.');await refresh()}catch(e){toast(e.message)}}
