function localEventInput(t){if(!t)return'';const d=new Date(t),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}
function eventById(id){return (state.data?.events||[]).find(x=>String(x.id)===String(id))}
function eventLocationMap(e){const m=e?.map;if(!m)return'';const pm=portalMap(),left=Math.max(0,Math.min(100,(Number(m.map_x)/pm.width)*100)),top=Math.max(0,Math.min(100,(Number(m.map_y)/pm.height)*100)),mapId=`eventMapViewport-${String(e.id||'event').replace(/[^a-zA-Z0-9_-]/g,'')}`;return `<section class="eventLocation"><div class="eventMapHeader"><div><span class="eyebrow">RECORDED EVENT LOCATION</span><h3>Sector ${esc(m.sector||'Unknown')}</h3></div><span class="coordBadge">X ${Number(e.coordinate_x).toFixed(0)} • Y ${Number(e.coordinate_y).toFixed(0)} • Z ${Number(e.coordinate_z).toFixed(0)}</span></div>${tileMapMarkup(mapId,left.toFixed(5),top.toFixed(5),4.2,'event')}<div class="rawCoords">${esc(e.coordinate_raw||`{X=${e.coordinate_x} Y=${e.coordinate_y} Z=${e.coordinate_z}}`)}</div></section>`}
function eventCard(e){const open=e.status==='open',thumb=Array.isArray(e.image_urls)&&e.image_urls[0]?`<div class="eventThumb"><img src="${esc(e.image_urls[0])}" alt="${esc(e.title||'Event')} image" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.closest('.eventThumb')?.classList.add('imageFailed');this.removeAttribute('src')"></div>`:'';return `<div class="card span6 eventCard" data-search="${esc(`${e.title} ${e.location||''} ${e.description||''} ${e.map?.sector||''}`.toLowerCase())}" onclick="openEvent('${esc(e.id)}')">${thumb}<div class="eventTop"><div><span class="eyebrow">${esc((e.recurrence_label||e.recurrence||'One-time').toUpperCase())}</span><h3>${esc(e.title)}</h3></div><span class="status ${open?'good':''}">${open?'OPEN':'CLOSED'}</span></div><p class="eventWhen">🕒 ${esc(e.formatted_time||fmt(e.event_time))}</p><p>📍 ${esc(e.location||'Location TBA')}${e.map?.sector?` • <b>Sector ${esc(e.map.sector)}</b>`:''}</p><p class="eventPreview">${esc(e.description||'')}</p><div class="eventFoot"><span>👥 ${Number(e.rsvp_count||0)} RSVP${Number(e.rsvp_count||0)===1?'':'s'}</span><b>${e.my_rsvp?'✅ YOU ARE GOING':'OPEN DETAILS →'}</b></div></div>`}
function renderEvents(v,d){title('OUTPOST OPERATIONS','Events');const events=d.events||[];const admin=(state.me.isOwner||state.me.permissions?.manage_events)?`<div class="card span12 manage"><div><small>ADMIN EVENT CONTROL</small><h3>Create and manage server events</h3><p>Add event images, paste exact SCUM coordinates, and Watcher will show the correct sector with a location marker.</p></div><button class="btn primary" onclick="openEventForm()">+ Create Event</button></div>`:'';v.innerHTML=`<div class="grid">${admin}<div class="card span12"><div class="searchbar"><input id="filter" placeholder="Search events, sectors, locations or descriptions" oninput="filterCards()"></div><div class="grid" id="cards">${events.map(eventCard).join('')||'<div class="empty">No upcoming events are currently posted.</div>'}</div></div></div>`}
function openEvent(id){const e=eventById(id);if(!e)return toast('Event not found.');const admin=(state.me.isOwner||state.me.permissions?.manage_events)?`<div class="detailActions"><button class="btn" onclick="openEventForm('${esc(e.id)}')">Edit Event</button>${(!e.channel_id||!e.message_id||String(e.message_id)==='portal')?`<button class="btn primary" onclick="retryEventPost('${esc(e.id)}')">Retry Discord Post</button>`:''}<button class="btn" onclick="eventStatus('${esc(e.id)}','${e.status==='open'?'closed':'open'}')">${e.status==='open'?'Close Event':'Reopen Event'}</button><button class="btn dangerBtn" onclick="deleteEvent('${esc(e.id)}')">Delete Event</button></div>`:'';const hasCoords=[e.coordinate_x,e.coordinate_y,e.coordinate_z].every(v=>Number.isFinite(Number(v)));const teleport=hasCoords?`<section class="eventTeleportPanel"><div><span class="eyebrow">EVENT TRANSPORT</span><h3>Watcher Event Teleport</h3><p id="eventTeleportStatus">Checking availability…</p></div><div class="detailActions"><button id="eventTeleportTo" class="btn primary" disabled onclick="eventTeleport('${esc(e.id)}','to')">Teleport to Event</button><button id="eventTeleportBack" class="btn" disabled onclick="eventTeleport('${esc(e.id)}','back')">Teleport Back</button></div></section>`:'';$('modalBody').innerHTML=`<div class="detailHero"><span class="eyebrow">${esc(e.recurrence_label||e.recurrence||'One-time')}</span><h2>${esc(e.title)}</h2><div class="detailMeta"><span>🕒 ${esc(e.formatted_time||fmt(e.event_time))}</span><span>📍 ${esc(e.location)}</span>${e.map?.sector?`<span>🗺️ Sector ${esc(e.map.sector)}</span>`:''}<span>👥 ${Number(e.rsvp_count||0)} attending</span></div></div>${detailImages(e.image_urls,'')}${eventLocationMap(e)}${teleport}<div class="detailText">${esc(e.description).replace(/\n/g,'<br>')}</div><div class="detailActions">${e.status==='open'?`<button class="btn ${e.my_rsvp?'':'primary'}" onclick="eventRsvp('${esc(e.id)}',${e.my_rsvp?'false':'true'})">${e.my_rsvp?'Cancel RSVP':'RSVP to Event'}</button>`:'<span class="status">EVENT CLOSED</span>'}</div>${admin}`;$('modal').querySelector('.modal').classList.add('detailModal');$('modal').classList.remove('hidden');setTimeout(()=>{const map=$('modalBody').querySelector('.zoomableMap');if(map)initZoomableMap(map.id);if(hasCoords)loadEventTeleportState(e.id)},0)}
async function loadEventTeleportState(id){const status=$('eventTeleportStatus'),to=$('eventTeleportTo'),back=$('eventTeleportBack');if(!status||!to||!back)return;try{const r=await api(`/portal/api/events/teleport-state?id=${encodeURIComponent(id)}`);to.disabled=!r.available;back.disabled=!r.available||!r.hasReturn;if(r.available)status.textContent=r.hasReturn?'Teleport is open. Your original position is saved and ready for return.':'Teleport is open. Watcher will save your current position before sending you.';else status.textContent=`Teleport opens 15 minutes before start: ${fmt(r.availableAt)}.`}catch(e){status.textContent=e.message;to.disabled=true;back.disabled=true}}
async function eventTeleport(id,action){const label=action==='back'?'return to your saved position':'teleport to this event';if(!confirm(`Watcher will ${label}. You must be online in SCUM. Continue?`))return;const to=$('eventTeleportTo'),back=$('eventTeleportBack');if(to)to.disabled=true;if(back)back.disabled=true;try{const r=await api('/portal/api/events/teleport',{method:'POST',body:JSON.stringify({id,action})});toast(`✅ Verified complete: ${r.message||'Teleport completed.'}`);await loadEventTeleportState(id)}catch(e){toast(e.message);await loadEventTeleportState(id)}}
function openEventForm(id=''){const e=id?eventById(id):null;$('modalBody').innerHTML=`<h2>${e?'Edit':'Create'} Event</h2><div class="eventComposer"><div class="formgrid"><label class="full">Event title<input id="evTitle" maxlength="100" value="${esc(e?.title||'')}" oninput="updateEventPreview()"></label><label>Location name<input id="evLocation" maxlength="200" value="${esc(e?.location||'')}" oninput="updateEventPreview()"></label><label>Date and time<input id="evTime" type="datetime-local" value="${localEventInput(e?.event_time)}" oninput="updateEventPreview()"></label><label>Recurrence<select id="evRecurrence" onchange="updateEventPreview()"><option value="none">One-time</option><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="biweekly">Biweekly</option><option value="monthly">Monthly</option></select></label><label class="full">SCUM coordinates <small>(optional)</small><textarea id="evCoordinates" rows="3" placeholder="{X=221249.375 Y=-291857.969 Z=17184.834|P=348.760956 Y=160.196045 R=0.000000}">${esc(e?.coordinate_raw||'')}</textarea></label><label class="full">Event images <small>(up to 5)</small><input id="evFiles" type="file" accept="image/*" multiple onchange="updateEventPreview()"><small>Discord uses only the first/main image. Extra images stay available in the Command Center.</small></label>${e&&Array.isArray(e.image_urls)&&e.image_urls.length?`<label class="checkline full"><input id="evRemoveImages" type="checkbox"> Remove all current event images</label>`:''}<label class="full">Description<textarea id="evDescription" rows="8" maxlength="2000" oninput="updateEventPreview()">${esc(e?.description||'')}</textarea></label></div><aside id="eventLivePreview" class="eventLivePreview"></aside></div><button class="btn primary" onclick="saveEvent('${esc(e?.id||'')}')">${e?'Save Changes':'Post Event'}</button>`;$('modal').querySelector('.modal').classList.add('detailModal');$('modal').classList.remove('hidden');$('evRecurrence').value=e?.recurrence||'none';window.eventPreviewExistingImage=Array.isArray(e?.image_urls)?e.image_urls[0]||'':'';updateEventPreview();const draftName=`event:${id||'new'}`;restoreDraft(draftName);armDraft(draftName)}
function updateEventPreview(){const box=$('eventLivePreview');if(!box)return;const file=$('evFiles')?.files?.[0];if(window.eventPreviewObjectUrl)URL.revokeObjectURL(window.eventPreviewObjectUrl);window.eventPreviewObjectUrl=file?URL.createObjectURL(file):'';const image=window.eventPreviewObjectUrl||window.eventPreviewExistingImage||'';const title=$('evTitle')?.value.trim()||'Your Event Title';const location=$('evLocation')?.value.trim()||'Location TBA';const description=$('evDescription')?.value.trim()||'Your event description will appear here.';const when=$('evTime')?.value?fmt(new Date($('evTime').value).toISOString()):'Date and time';box.innerHTML=`<small>DISCORD / MOBILE PREVIEW</small><div class="previewEmbed">${image?`<img src="${esc(image)}" alt="Event preview">`:'<div class="previewNoImage">MAIN IMAGE</div>'}<div><b>${esc(title)}</b><span>🕒 ${esc(when)}</span><span>📍 ${esc(location)}</span><p>${esc(description.slice(0,260))}</p></div></div>`}
async function saveEvent(id){const title=$('evTitle').value.trim(),location=$('evLocation').value.trim(),description=$('evDescription').value.trim(),coordinates=$('evCoordinates').value.trim(),raw=$('evTime').value,recurrence=$('evRecurrence').value,files=$('evFiles');if(!title||!location||!description||!raw)return toast('Complete every required event field.');const eventTime=new Date(raw).toISOString();try{const images=files?.files?.length?await filesToData(files):[];const removeImages=!!$('evRemoveImages')?.checked;const replaceImages=!!images.length||removeImages;const result=await api(id?'/portal/api/events/update':'/portal/api/events/create',{method:'POST',body:JSON.stringify({id,title,location,description,coordinates,eventTime,recurrence,images,replaceImages})});closeModal();clearDraft(`event:${id||'new'}`);await refresh();go('events');showEventPostResult(result.event,!!result.discordPost?.ok)}catch(e){toast(e.message)}}
function showEventPostResult(event,ok){$('modalBody').innerHTML=`<div class="postResult ${ok?'ok':'bad'}"><i>${ok?'✓':'!'}</i><h2>${ok?'Event saved and posted':'Event saved, but Discord posting failed'}</h2><p>${ok?'Watcher confirmed the public Event News message.':'The event is saved in the Command Center. Retry the Discord post without recreating it.'}</p>${ok?'':`<button class="btn primary" onclick="retryEventPost('${esc(event?.id||'')}')">Retry Discord Post</button>`}<button class="btn" onclick="closeModal()">Close</button></div>`;$('modal').classList.remove('hidden')}
async function retryEventPost(id){try{const r=await api('/portal/api/events/retry-post',{method:'POST',body:JSON.stringify({id})});await refresh();showEventPostResult(r.event,true)}catch(e){toast(e.message)}}
async function eventRsvp(id,attending){try{await api('/portal/api/events/rsvp',{method:'POST',body:JSON.stringify({id,attending})});closeModal();toast(attending?'RSVP saved. Reminders are enabled.':'RSVP removed.');await refresh();go('events')}catch(e){toast(e.message)}}
async function eventStatus(id,status){if(!confirm(`${status==='open'?'Reopen':'Close'} this event?`))return;try{await api('/portal/api/events/status',{method:'POST',body:JSON.stringify({id,status})});closeModal();toast(`Event ${status==='open'?'reopened':'closed'}.`);await refresh();go('events')}catch(e){toast(e.message)}}
async function deleteEvent(id){if(!confirm('Permanently delete this event, its Discord post and all RSVPs?'))return;try{await api('/portal/api/events/delete',{method:'POST',body:JSON.stringify({id})});closeModal();toast('Event deleted.');await refresh();go('events')}catch(e){toast(e.message)}}

function renderHistory(v,tx,admin){if(v.id!=='adminLedger')title(admin?'ADMIN LEDGER':'WATCHER LEDGER',admin?'Transaction Control':'My Watcher History');v.innerHTML=`<div class="card"><div class="tableWrap"><table class="table"><thead><tr><th>Date</th>${admin?'<th>Player</th>':''}<th>Action</th><th>Amount</th><th>Status</th>${admin?'<th>Admin</th>':''}</tr></thead><tbody>${tx.map(x=>`<tr><td>${fmt(x.created_at)}</td>${admin?`<td>${esc(x.player_name||x.steam_id||'Unknown')}</td>`:''}<td>${esc(x.title||x.type)}</td><td class="amount ${Number(x.amount)>=0?'pos':'neg'}">${Number(x.amount)?money(x.amount):'—'}</td><td>${esc(x.refund_status||x.status)}</td>${admin?`<td>${(state.me.isOwner||state.me.permissions?.issue_refunds)&&x.refundable&&Math.abs(Number(x.amount||0))>Number(x.refunded_amount||0)?`<button class="btn" onclick='refund(${JSON.stringify(x)})'>Refund</button>`:'—'}</td>`:''}</tr>`).join('')||'<tr><td colspan="6" class="empty">No Watcher history in the last 15 days.</td></tr>'}</tbody></table></div></div>`}
function renderAdmin(v,d){if(!state.me.isAdmin)return go('dashboard');title('ADMIN OPERATIONS','Watcher Control Deck');const p=state.me.permissions||{};const quick=[];if(state.me.isOwner||p.search_players){quick.push(`<button class="mobileAdminTile" onclick="adminTab('players')"><i>🔎</i><b>Find Player</b><span>Account, vehicles, balances and moderation</span></button>`);quick.push(`<button class="mobileAdminTile unregisteredTile" onclick="adminTab('unregistered')"><i>⚠️</i><b>Active Without Discord</b><span id="unregisteredQuickCount">Check active players with no known registration</span></button>`);quick.push(`<button class="mobileAdminTile" onclick="adminTab('abandonedVehicles')"><i>🚙</i><b>Vehicle Activity</b><span>Read-only abandoned vehicle review</span></button>`);quick.push(`<button class="mobileAdminTile" onclick="adminTab('baseFlags')"><i>🚩</i><b>Base Flags</b><span>Owners, locations and building usage</span></button>`);}if(state.me.isOwner||p.spawn_items_vehicles)quick.push(`<button class="mobileAdminTile" onclick="adminTab('spawnTools')"><i>📦</i><b>Spawn Tools</b><span>Spawn an item or vehicle to an online player</span></button>`);if(state.me.isOwner||p.view_transactions){quick.push(`<button class="mobileAdminTile" onclick="adminTab('ledger')"><i>🧾</i><b>Ledger</b><span>Transactions and approved refunds</span></button>`);quick.push(`<button class="mobileAdminTile" onclick="adminTab('pendingRewards')"><i>🎁</i><b>Pending Rewards</b><span>Saved pop-up rewards awaiting delivery</span></button>`);}if(state.me.isOwner||p.manage_events)quick.push(`<button class="mobileAdminTile" onclick="adminTab('eventTriggers')"><i>⚡</i><b>Events</b><span>Launch and monitor Watcher events</span></button>`);if(state.me.isOwner||p.manage_server_shop){quick.push(`<button class="mobileAdminTile" onclick="adminTab('serverShop')"><i>🛒</i><b>Shop</b><span>Manage emergency shop products</span></button>`);quick.push(`<button class="mobileAdminTile" onclick="adminTab('catalogValidation')"><i>🧪</i><b>Catalog Validation</b><span>Find invalid, duplicate, or missing pack items</span></button>`);}if(state.me.isOwner||p.moderate_player_shops||p.moderate_player_lore||p.moderate_squads)quick.push(`<button class="mobileAdminTile" onclick="adminTab('content')"><i>🛡️</i><b>Moderation</b><span>Review shops, squads and lore</span></button>`);if(state.me.isOwner||p.use_surveillance)quick.push(`<button class="mobileAdminTile surveillanceTile" onclick="go('surveillance')"><i>👁️</i><b>Surveillance</b><span>Mobile simplified mode available</span></button>`);const tabs=[];if(state.me.isOwner||p.search_players){tabs.push(`<button class="btn primary" onclick="adminTab('players')">Player Controls</button>`);tabs.push(`<button class="btn" onclick="adminTab('unregistered')">Active Without Discord</button>`);tabs.push(`<button class="btn" onclick="adminTab('abandonedVehicles')">Vehicle Activity Review</button>`);tabs.push(`<button class="btn" onclick="adminTab('baseFlags')">Base Flag Overview</button>`);}if(state.me.isOwner||p.spawn_items_vehicles)tabs.push(`<button class="btn" onclick="adminTab('spawnTools')">Item / Vehicle Spawn Tools</button>`);if(state.me.isOwner||p.view_transactions){tabs.push(`<button class="btn" onclick="adminTab('ledger')">Transaction Ledger & Refunds</button>`);tabs.push(`<button class="btn" onclick="adminTab('pendingRewards')">Pending Rewards</button>`);}if(state.me.isOwner||p.moderate_player_shops||p.moderate_player_lore||p.moderate_squads)tabs.push(`<button class="btn" onclick="adminTab('content')">Player Content Moderation</button>`);if(state.me.isOwner||p.manage_events)tabs.push(`<button class="btn" onclick="adminTab('eventTriggers')">Admin Event Triggers</button>`);if(state.me.isOwner||p.manage_server_shop){tabs.push(`<button class="btn" onclick="adminTab('serverShop')">Server Shop Manager</button>`);tabs.push(`<button class="btn" onclick="adminTab('catalogValidation')">Catalog Validation</button>`);}v.innerHTML=`<div class="mobileAdminIntro card"><div><small>MOBILE ADMIN WORKSPACE</small><h3>Watcher tools sized for phone use</h3><p>Tap a tool below. Powerful actions still require confirmation and your live Discord permissions.</p></div></div><div class="adminToolFinder"><input id="adminToolSearch" placeholder="Search admin tools" oninput="filterAdminTools()"><button class="btn" onclick="$('adminToolSearch').value='';filterAdminTools();$('adminToolSearch').focus()">Clear</button></div><div class="adminToolGroups">${groupedAdminTiles(quick)}</div><div id="adminToolEmpty" class="card empty" hidden>No admin tools match that search.</div><div class="adminTabs" aria-hidden="true">${tabs.join('')}</div><div id="adminArea"></div><div class="grid adminSystemPanels"><div class="card span6"><div class="cardHeading"><div><small>SYSTEM HEALTH</small><h3>Watcher Connections</h3></div><button class="btn" onclick="loadSystemHealth()">Run Checks</button></div><div id="systemHealth" class="list"><div class="empty">Checking Watcher, Supabase, GGCON, Event News, and surveillance storage…</div></div></div><div class="card span6"><div class="cardHeading"><div><small>RECENT ADMIN ACTIVITY</small><h3>Latest Watcher Records</h3></div>${state.me.isOwner?'<button class="btn" onclick="exportPortalBackup()">Export Backup</button>':''}</div>${adminActivityMarkup(state.data?.adminRecentActivity||[])}</div></div>`;setTimeout(loadSystemHealth,0);setTimeout(loadActiveUnregisteredCount,0);adminTab(state.me.isOwner||p.search_players?'players':state.me.isOwner||p.view_transactions?'ledger':state.me.isOwner||p.manage_server_shop?'serverShop':state.me.isOwner||p.manage_events?'eventTriggers':'content')}
function adminActivityMarkup(rows){return `<div class="activityList">${rows.length?rows.slice(0,8).map(x=>`<div class="activityRow"><span class="activityIcon">${activityIcon(x.type)}</span><span><b>${esc(x.title||x.type||'Watcher action')}</b><small>${esc(x.player_name||x.steam_id||'System')} • ${fmt(x.created_at)}</small></span><strong>${Number(x.amount||0)?money(Math.abs(Number(x.amount))):esc(x.status||'')}</strong></div>`).join(''):'<div class="empty">No recent Watcher records.</div>'}</div>`}
async function loadSystemHealth(){const box=$('systemHealth');if(!box)return;box.innerHTML='<div class="empty">Watcher is checking every connection…</div>';try{const r=await api('/portal/api/admin/health');box.innerHTML=Object.entries(r.checks||{}).map(([k,v])=>`<div class="row healthRow"><div><b>${esc(k.replace(/([A-Z])/g,' $1').replace(/^./,x=>x.toUpperCase()))}</b><small>${esc(v.detail)}</small></div><span class="status ${v.ok?'good':'bad'}">${v.ok?'ONLINE':'ISSUE'}</span></div>`).join('')+`${r.config?`<div class="healthMeta"><b>Configuration</b><span>${Object.entries(r.config).filter(([,v])=>v).length}/${Object.keys(r.config).length} required connections configured</span></div>`:''}${Array.isArray(r.scheduler)?`<div class="healthMeta"><b>Scheduler</b><span>${r.scheduler.length} coordinated tasks • ${r.scheduler.filter(x=>x.running).length} running now</span></div>`:''}${r.retryQueue?.length?`<div class="healthMeta warning"><b>Retry Queue</b><span>${r.retryQueue.length} safe action(s) awaiting retry</span></div>`:''}<small class="healthChecked">Checked ${fmt(r.checkedAt)} • Version ${esc(r.version)}</small>`}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function exportPortalBackup(){try{const data=await api('/portal/api/owner/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`outpost-x-portal-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Portal backup exported.')}catch(e){toast(e.message)}}
function adminTab(tab){state.adminSubtab=tab||'players';markAdminToolActive(state.adminSubtab);if(state.adminSubtab!=='players')state.selectedAdminPlayer=null;const a=$('adminArea');if(!a)return;if(tab==='unregistered'){renderActiveUnregistered(a);return}if(tab==='abandonedVehicles'){renderAbandonedVehicles(a,14);return}if(tab==='baseFlags'){renderBaseFlags(a);return}if(tab==='spawnTools'){renderAdminSpawnTools(a);return}if(tab==='ledger'){renderAdminLedger(a);return}if(tab==='pendingRewards'){renderPendingRewards(a);return}if(tab==='content'){renderContentModeration(a);return}if(tab==='serverShop'){renderServerShopManager(a);return}if(tab==='catalogValidation'){renderCatalogValidation(a);return}if(tab==='eventTriggers'){renderAdminEventTriggers(a);return}if(tab==='owner'){renderOwnerControls(a);return}a.innerHTML=`<div class="grid"><div class="card span12"><h3>Find a Player</h3><p style="color:var(--muted)">Search by SCUM name or Steam64 ID. Raw log/data-pull commands stay in Discord and are intentionally not shown here.</p><div class="searchbar"><input id="adminSearch" placeholder="Player name or Steam64 ID" onkeydown="if(event.key==='Enter')adminSearch()"><button class="btn primary" onclick="adminSearch()">Search</button></div><div id="adminResults" class="list"></div></div><div id="adminPlayer" class="span12"></div></div>`}

let specialEventAdminData={event:{active:false},onlinePlayers:[]};
function eventRemainingLabel(event){if(!event?.active)return 'No special event is currently active.';const left=Math.max(0,Number(event.endsAt||0)-Date.now());const min=Math.floor(left/60000),sec=Math.floor((left%60000)/1000);return `${event.type==='hunt'?'Watcher Hunt':event.type==='risk'?'Risk or Reward':'Special Event'} • ${event.phase||'active'} • ${min}m ${sec}s remaining`;}
async function renderAdminEventTriggers(a){
  a.innerHTML=`<div class="grid"><div class="card span12"><div class="sectionHead"><div><small>WATCHER SPECIAL EVENTS</small><h2>Admin Event Triggers</h2><p>Launch and monitor special in-game Watcher events. Players join and interact entirely through SCUM chat.</p></div><button class="btn" onclick="loadAdminEventTriggers()">Refresh Status</button></div><div id="specialEventStatus" class="list"><div class="empty">Loading event status…</div></div></div><div id="specialEventCards" class="span12"></div></div>`;
  await loadAdminEventTriggers();
}
async function loadAdminEventTriggers(){
  const statusBox=$('specialEventStatus'),cards=$('specialEventCards');
  try{
    specialEventAdminData=await api('/portal/api/admin/event-triggers');
    const e=specialEventAdminData.event||{active:false};
    statusBox.innerHTML=e.active?`<div class="row"><div><b>${esc(eventRemainingLabel(e))}</b><small>${e.type==='hunt'?`Participants: ${Number(e.participantCount||0)} • Hidden bounty: ${esc(e.bounty?.name||'Unknown')} • Win radius: 50 m`:e.type==='risk'?`Contestant: ${esc(e.contestant?.name||'Waiting for player')} • Safe ${money(e.safeReward)} • Maximum ${money(e.maxReward)}`:'Active special event'}</small></div><button class="btn dangerBtn" onclick="endSpecialEvent()">End Active Event</button></div>`:`<div class="empty">No special event is active. Choose one below.</div>`;
    const players=(specialEventAdminData.onlinePlayers||[]).filter(x=>x.steamId);
    const playerOptions=['<option value="">Random online player</option>',...players.map(x=>`<option value="${esc(x.steamId)}">${esc(x.name)} — ${esc(x.steamId)}</option>`)].join('');
    cards.innerHTML=`<div class="grid">
      <article class="card span4"><small>CARGO FRENZY</small><h3>Scatter Cargo Across the Island</h3><p>Launch the existing safe-spawn Cargo Frenzy from the Command Center.</p><label>Number of cargo drops<input id="cargoTriggerCount" type="number" min="1" max="30" value="10"></label><button class="btn primary" onclick="startCargoTrigger()" ${e.active?'disabled':''}>Trigger Cargo Frenzy</button></article>
      <article class="card span4"><small>WATCHER HUNT</small><h3>Hidden Bounty Hunt</h3><p>Players type <b>!hunt</b> in SCUM chat to join and <b>!scan</b> for private directional clues.</p><div class="formgrid"><label class="full">Hidden bounty<select id="huntBounty">${playerOptions}</select></label><label>Join window (seconds)<input id="huntJoinSeconds" type="number" min="30" max="300" value="120"></label><label>Duration (minutes)<input id="huntDuration" type="number" min="5" max="60" value="20"></label><label>Scan cooldown (seconds)<input id="huntScanCooldown" type="number" min="10" max="180" value="30"></label><label>Winner reward<input id="huntReward" type="number" min="0" step="100" value="2500"></label><label class="full form-check form-switch"><input class="form-check-input" id="huntAllowStaff" type="checkbox" checked><span class="form-check-label">Allow Owner/Admin as the bounty</span></label></div><button class="btn primary" onclick="startWatcherHunt()" ${e.active?'disabled':''}>Start Watcher Hunt</button><small>First registered hunter confirmed within 50 metres for two samples wins.</small></article>
      <article class="card span4"><small>RISK OR REWARD</small><h3>Make a Watcher Offer</h3><p>First eligible player to type <b>!risk</b> chooses <b>!safe</b> or <b>!riskit</b> privately in-game.</p><div class="formgrid"><label>Safe reward<input id="riskSafeReward" type="number" min="0" step="100" value="500"></label><label>Maximum reward<input id="riskMaxReward" type="number" min="500" step="100" value="3000"></label><label>Acceptance window (seconds)<input id="riskAcceptSeconds" type="number" min="30" max="300" value="90"></label><label class="form-check form-switch"><input class="form-check-input" id="riskAllowStorm" type="checkbox" checked><span class="form-check-label">Allow Watcher storm outcome</span></label></div><button class="btn primary" onclick="startRiskReward()" ${e.active?'disabled':''}>Start Risk or Reward</button></article>
    </div>`;
  }catch(err){statusBox.innerHTML=`<div class="empty">${esc(err.message)}</div>`;if(cards)cards.innerHTML='';}
}
async function triggerSpecialEvent(action,options={}){try{await api('/portal/api/admin/event-triggers',{method:'POST',body:JSON.stringify({action,options})});toast(action==='cargo'?'Cargo Frenzy triggered.':action==='hunt'?'Watcher Hunt started.':action==='risk'?'Risk or Reward started.':'Special event updated.');await loadAdminEventTriggers()}catch(err){toast(err.message)}}
function startCargoTrigger(){triggerSpecialEvent('cargo',{count:Number($('cargoTriggerCount')?.value||10)})}
function startWatcherHunt(){triggerSpecialEvent('hunt',{bountySteamId:$('huntBounty')?.value||'',allowStaffBounty:!!$('huntAllowStaff')?.checked,joinSeconds:Number($('huntJoinSeconds')?.value||120),durationMinutes:Number($('huntDuration')?.value||20),scanCooldownSeconds:Number($('huntScanCooldown')?.value||30),rewardCash:Number($('huntReward')?.value||2500)})}
function startRiskReward(){triggerSpecialEvent('risk',{safeReward:Number($('riskSafeReward')?.value||500),maxReward:Number($('riskMaxReward')?.value||3000),acceptSeconds:Number($('riskAcceptSeconds')?.value||90),allowStorm:!!$('riskAllowStorm')?.checked})}
async function endSpecialEvent(){if(!confirm('End the currently active Watcher special event?'))return;await triggerSpecialEvent('end',{reason:'Ended by staff from the Command Center'})}
function renderContentModeration(a){const d=state.data,p=state.me.permissions||{},owner=state.me.isOwner;const cards=[];if(owner||p.moderate_player_shops)cards.push(`<div class="card span4"><h3>Player Shops</h3><div class="list">${(d.shops||[]).map(x=>moderationRow('shop',x.id,x.shop_name,x.is_open?'OPEN':'CLOSED')).join('')||'<div class="empty">None</div>'}</div></div>`);if(owner||p.moderate_squads)cards.push(`<div class="card span4"><h3>Squad Listings</h3><div class="list">${(d.squads||[]).map(x=>moderationRow('squad',x.id,x.squad_name,x.is_recruiting?'RECRUITING':'CLOSED')).join('')||'<div class="empty">None</div>'}</div></div>`);if(owner||p.moderate_player_lore)cards.push(`<div class="card span4"><h3>Player Lore</h3><div class="list">${[...(d.lore||[]),...(d.myLore&&!d.lore?.some(x=>x.id===d.myLore.id)?[d.myLore]:[])].map(x=>moderationRow('lore',x.id,x.character_name,x.is_published?'PUBLISHED':'HIDDEN')).join('')||'<div class="empty">None</div>'}</div></div>`);a.innerHTML=`<div class="grid">${cards.join('')||'<div class="card span12 empty">No content moderation permissions are enabled for your role.</div>'}</div>`}
function moderationRow(kind,id,name,status){return `<div class="row"><div><b>${esc(name)}</b><small>${esc(status)}</small></div><div><button class="btn" onclick="moderateContent('${kind}','${esc(id)}','toggle')">Toggle</button> <button class="btn dangerBtn" onclick="moderateContent('${kind}','${esc(id)}','delete')">Delete</button></div></div>`}
async function moderateContent(kind,id,action){if(action==='delete'&&!confirm(`Delete this ${kind} permanently?`))return;try{await api('/portal/api/admin/content',{method:'POST',body:JSON.stringify({kind,id,action})});toast('Content updated.');await refresh();go('admin');adminTab('content')}catch(e){toast(e.message)}}
function renderAdminLedger(a){
  const l=state.adminLedger;
  a.innerHTML=`<div class="card ledgerControls"><div class="ledgerToolbar"><div class="ledgerSearch"><input id="ledgerSearch" value="${esc(l.search)}" placeholder="Search player, Steam ID or action" onkeydown="if(event.key==='Enter')applyLedgerFilters()"><button class="btn primary" onclick="applyLedgerFilters()">Search</button></div><label>Type<select id="ledgerCategory" onchange="applyLedgerFilters()"><option value="all">All Watcher Activity</option><option value="server_shop">Server Shop</option><option value="insurance">Insurance</option><option value="taxi">Airlift Taxi</option><option value="rental">Dirtbike Rental</option><option value="refund">Refunds</option><option value="admin">Admin Adjustments</option></select></label><label>Status<select id="ledgerStatus" onchange="applyLedgerFilters()"><option value="all">All Statuses</option><option value="completed">Completed</option><option value="failed">Failed</option><option value="refunded">Partially / Fully Refunded</option></select></label><label>Rows<select id="ledgerPageSize" onchange="applyLedgerFilters()"><option>25</option><option>50</option><option>100</option></select></label><button class="btn" onclick="resetLedgerFilters()">Clear Filters</button></div><div class="ledgerSummary"><span id="ledgerSummary">Loading transactions…</span><small>Watcher activity from the last 15 days only.</small></div></div><div id="adminLedger"><div class="card empty">Loading transaction ledger…</div></div>`;
  $('ledgerCategory').value=l.category;$('ledgerStatus').value=l.status;$('ledgerPageSize').value=String(l.pageSize);loadAdminLedger();
}
async function loadAdminLedger(){
  const l=state.adminLedger,box=$('adminLedger');if(!box)return;box.innerHTML='<div class="card empty">Watcher is loading transactions…</div>';
  const q=new URLSearchParams({page:String(l.page),pageSize:String(l.pageSize),category:l.category,status:l.status});if(l.search)q.set('search',l.search);
  try{const r=await api(`/portal/api/admin/transactions?${q}`);l.rows=r.transactions||[];l.total=Number(r.total||0);l.page=Number(r.page||1);l.pages=Number(r.pages||1);drawAdminLedger(box);}
  catch(e){box.innerHTML=`<div class="card empty">${esc(e.message)}</div>`}
}
function drawAdminLedger(box){
  const l=state.adminLedger;const canRefund=state.me.isOwner||state.me.permissions?.issue_refunds;
  $('ledgerSummary').textContent=`${l.total.toLocaleString()} transaction${l.total===1?'':'s'} • Page ${l.page} of ${l.pages}`;
  box.innerHTML=`<div class="card"><div class="tableWrap"><table class="table"><thead><tr><th>Date</th><th>Player</th><th>Action</th><th>Amount</th><th>Status</th><th>Admin</th></tr></thead><tbody>${l.rows.map(x=>`<tr><td>${fmt(x.created_at)}</td><td><b>${esc(x.player_name||'Unknown')}</b><small class="ledgerSteam">${esc(x.steam_id||'')}</small></td><td>${esc(x.title||x.type)}</td><td class="amount ${Number(x.amount)>=0?'pos':'neg'}">${Number(x.amount)?money(x.amount):'—'}</td><td>${esc(x.refund_status||x.status)}</td><td>${canRefund&&x.refundable&&Math.abs(Number(x.amount||0))>Number(x.refunded_amount||0)?`<button class="btn" onclick='refund(${JSON.stringify(x)})'>Refund</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No transactions match these filters.</td></tr>'}</tbody></table></div><div class="ledgerPager"><button class="btn" ${l.page<=1?'disabled':''} onclick="ledgerPage(${l.page-1})">← Previous</button><span>Page ${l.page} of ${l.pages}</span><button class="btn" ${l.page>=l.pages?'disabled':''} onclick="ledgerPage(${l.page+1})">Next →</button></div></div>`;
}
function applyLedgerFilters(){const l=state.adminLedger;l.search=($('ledgerSearch')?.value||'').trim();l.category=$('ledgerCategory')?.value||'all';l.status=$('ledgerStatus')?.value||'all';l.pageSize=Number($('ledgerPageSize')?.value||25);l.page=1;loadAdminLedger()}
function resetLedgerFilters(){state.adminLedger={page:1,pageSize:25,category:'all',status:'all',search:'',total:0,pages:1,rows:[]};renderAdminLedger($('adminArea'))}
function ledgerPage(page){const l=state.adminLedger;l.page=Math.max(1,Math.min(l.pages,Number(page)||1));loadAdminLedger();document.querySelector('.ledgerControls')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function adminSearch(){const q=$('adminSearch').value.trim();if(!q)return toast('Enter a player name or Steam ID.');try{const r=await api('/portal/api/admin/search',{method:'POST',body:JSON.stringify({query:q})});$('adminResults').innerHTML=(r.players||[]).map(p=>`<button class="row adminresult" onclick="openAdminPlayer('${esc(p.steamId)}','${esc(p.name)}')"><div><b>${esc(p.name)}</b><small>${esc(p.steamId)}</small></div><span class="status ${p.online?'good':''}">${p.online?'ONLINE':'OFFLINE'}</span></button>`).join('')||'<div class="empty">No players matched that search.</div>'}catch(e){toast(e.message)}}
function openAdminPlayer(steamId,name){state.selectedAdminPlayer={steamId:String(steamId),name:String(name||steamId)};const p=state.me.permissions||{},owner=state.me.isOwner;const buttons=[`<button class="btn primary" onclick="adminView('${steamId}','details')">Player Details</button>`,`<button class="btn" onclick="adminView('${steamId}','vehicles')">Vehicles</button>`,`<button class="btn" onclick="adminView('${steamId}','squad')">Squad</button>`,`<button class="btn" onclick="adminView('${steamId}','nearby')">Nearby Vehicles</button>`,`<button class="btn" onclick="copySteamId('${steamId}')">Copy Steam64</button>`,`<button class="btn" onclick="openPlayerTransactions('${steamId}')">Transactions</button>`];if(owner||p.spawn_items_vehicles)buttons.push(`<button class="btn" onclick="openSpawnForPlayer('${steamId}','${esc(String(name).replaceAll("'","&#39;"))}','item')">Spawn Item</button>`,`<button class="btn" onclick="openSpawnForPlayer('${steamId}','${esc(String(name).replaceAll("'","&#39;"))}','vehicle')">Spawn Vehicle</button>`);if(owner||p.adjust_balances)buttons.push(`<button class="btn" onclick="adminAdjustOpen('${steamId}','cash',1)">Add Cash</button>`,`<button class="btn dangerBtn" onclick="adminAdjustOpen('${steamId}','cash',-1)">Remove Cash</button>`,`<button class="btn" onclick="adminAdjustOpen('${steamId}','fame',1)">Add Fame</button>`,`<button class="btn dangerBtn" onclick="adminAdjustOpen('${steamId}','fame',-1)">Remove Fame</button>`);if(owner||p.jail_release)buttons.push(`<button class="btn dangerBtn" onclick="adminJail('${steamId}','jail')">Jail</button>`,`<button class="btn" onclick="adminJail('${steamId}','unjail')">Unjail</button>`);if(owner||p.ban_unban)buttons.push(`<button class="btn dangerBtn" onclick="adminModerateOpen('${steamId}','ban')">Ban Player</button>`,`<button class="btn" onclick="adminModerateOpen('${steamId}','unban')">Unban Player</button>`);buttons.push(`<button class="btn" onclick="adminIpLocation('${steamId}')">Approximate IP Location</button>`);if(owner||p.teleport_surveillance)buttons.push(`<button class="btn" onclick="adminTeleportOpen('${steamId}')">Direct Teleport</button>`);if(owner||p.ban_unban)buttons.push(`<button class="btn dangerBtn" onclick="adminKick('${steamId}')">Kick from SCUM</button>`);buttons.push(`<button class="btn dangerBtn" onclick="adminModerateOpen('${steamId}','unlink')">Unlink Discord</button>`);$('adminPlayer').innerHTML=`<div class="card"><div class="playerHead"><div><small>SELECTED PLAYER</small><h2>${esc(name)}</h2><span>${esc(steamId)}</span><small class="onlineFreshness">Watcher rechecks online status immediately before deliveries and other live GGCON actions.</small></div><button class="btn" onclick="adminView('${steamId}','details')">Refresh Details</button></div><div class="adminActions">${buttons.join('')}</div><pre class="adminOutput" id="adminOutput">Select an action above.</pre></div>`;adminView(steamId,'details')}
function copySteamId(steamId){navigator.clipboard?.writeText(String(steamId)).then(()=>toast('Steam64 copied.','good')).catch(()=>prompt('Copy Steam64:',steamId))}
function openPlayerTransactions(steamId){state.adminLedger.search=String(steamId);state.adminLedger.page=1;adminTab('ledger')}
async function openSpawnForPlayer(steamId,name,kind){state.preselectedSpawnPlayer={steamId:String(steamId),name:String(name),kind};adminTab('spawnTools')}

async function adminView(steamId,view){const o=$('adminOutput');o.textContent='Watcher is loading…';try{const r=await api('/portal/api/admin/player',{method:'POST',body:JSON.stringify({steamId,view})});o.textContent=r.content||'No data returned.'}catch(e){o.textContent=e.message}}
async function adminIpLocation(steamId){const o=$('adminOutput');o.textContent='Watcher is checking the player’s recent IP and approximate network location…';try{const r=await api('/portal/api/admin/ip-location',{method:'POST',body:JSON.stringify({steamId})});o.textContent=r.content||'No location data returned.'}catch(e){o.textContent=e.message}}
function adminAdjustOpen(steamId,kind,sign){$('modalBody').innerHTML=`<h2>${sign>0?'Add':'Remove'} ${kind==='cash'?'Cash':'Fame'}</h2><div class="formgrid"><label>Amount<input id="adminAmount" type="number" min="1"></label><label class="full">Required reason<textarea id="adminReason" rows="4"></textarea></label></div><button class="btn primary" onclick="adminAdjust('${steamId}','${kind}',${sign})">Confirm Adjustment</button>`;$('modal').classList.remove('hidden')}
async function adminAdjust(steamId,kind,sign){const n=Math.floor(Number($('adminAmount').value)),reason=$('adminReason').value.trim();if(!n||n<1||!reason)return toast('Enter an amount and reason.');try{await api('/portal/api/admin/adjust',{method:'POST',body:JSON.stringify({steamId,kind,amount:n*sign,reason})});closeModal();toast('✅ Verified complete: Player balance updated.');adminView(steamId,'details')}catch(e){toast(e.message)}}
function adminTeleportOpen(steamId){$('modalBody').innerHTML=`<h2>Direct GGCON Teleport</h2><p class="adminNotice">The player must still be online when you confirm.</p><div class="formgrid"><label>X coordinate<input id="directTpX" type="number" step="any"></label><label>Y coordinate<input id="directTpY" type="number" step="any"></label><label>Z coordinate<input id="directTpZ" type="number" step="any"></label></div><button class="btn primary" onclick="adminTeleport('${steamId}')">Teleport Player</button>`;$('modal').classList.remove('hidden')}
async function adminTeleport(steamId){const x=Number($('directTpX').value),y=Number($('directTpY').value),z=Number($('directTpZ').value);if(![x,y,z].every(Number.isFinite))return toast('Enter valid X, Y and Z coordinates.');if(!confirmWatcherAction({action:'Teleport player',steamId,details:`Coordinates: ${x}, ${y}, ${z}`}))return;try{const r=await api('/portal/api/admin/direct-action',{method:'POST',body:JSON.stringify({action:'teleport',steamId,x,y,z})});closeModal();toast(`✅ Verified complete: ${r.message||'Player teleported.'}`)}catch(e){toast(e.message)}}
async function adminKick(steamId){if(!confirmWatcherAction({action:'Kick player from SCUM',steamId,details:'This does not ban the player.'}))return;try{const r=await api('/portal/api/admin/direct-action',{method:'POST',body:JSON.stringify({action:'kick',steamId})});toast(`✅ Verified complete: ${r.message||'Player kicked.'}`)}catch(e){toast(e.message)}}

async function renderBaseFlags(a){a.innerHTML=`<div class="card"><div class="cardHeading"><div><small>GGCON BASE REGISTRY</small><h3>Base Flag Overview</h3><p>Read-only owner, location and building-element information.</p></div><button class="btn" onclick="renderBaseFlags($('adminArea'))">Refresh Flags</button></div><div id="baseFlagSummary" class="adminNotice">Loading flags…</div><div id="baseFlagList" class="list"></div></div>`;try{const d=await api('/portal/api/admin/base-flags');$('baseFlagSummary').innerHTML=`Flags: <b>${Number(d.count||0)}</b> • Server cap: <b>${d.rules?.maxElementsPerFlag??'Unknown'}</b> • Extra per squad member: <b>${d.rules?.extraElementsPerSquadMember??'Unknown'}</b>`;$('baseFlagList').innerHTML=(d.flags||[]).map(f=>{const loc=f.location?`${Math.round(Number(f.location.x||0))}, ${Math.round(Number(f.location.y||0))}, ${Math.round(Number(f.location.z||0))}`:'Unknown';const pct=f.maxElements?Math.min(100,Math.round(Number(f.elementCount||0)/Number(f.maxElements)*100)):null;return `<div class="flagCard"><div class="row"><div><b>${esc(f.baseName||`Base #${f.baseId||f.flagId}`)}</b><small>${f.owner?`Owner: ${esc(f.owner)}${f.ownerSteamId?` (${esc(f.ownerSteamId)})`:''}`:'Owner unavailable'} • Location: ${esc(loc)}</small></div><span class="status ${pct!==null&&pct>=90?'bad':pct!==null&&pct>=75?'warning':'good'}">${Number(f.elementCount||0)}${f.maxElements?` / ${Number(f.maxElements)}`:''}</span></div>${pct!==null?`<div class="flagMeter"><i style="width:${pct}%"></i></div><small>${pct}% of reported base limit • Expanded: ${Number(f.expandedElements||0)}</small>`:''}</div>`}).join('')||'<div class="empty">No base flags were returned by GGCON.</div>'}catch(e){$('baseFlagSummary').textContent=e.message}}

async function adminJail(steamId,action){if(!confirm(`${action==='jail'?'Jail':'Release'} this player?`))return;try{const r=await api('/portal/api/admin/jail',{method:'POST',body:JSON.stringify({steamId,action})});toast(`✅ Verified complete: ${r.message||'Action completed.'}`);adminView(steamId,'details')}catch(e){toast(e.message)}}
function adminModerateOpen(steamId,action){const word=action.toUpperCase(),needsReason=action!=='unlink';$('modalBody').innerHTML=`<h2>${word} Player</h2>${needsReason?'<label>Required reason<textarea id="modReason" rows="4"></textarea></label>':''}<label>Type ${word} to confirm<input id="modConfirm"></label><button class="btn ${action==='ban'||action==='unlink'?'dangerBtn':'primary'}" onclick="adminModerate('${steamId}','${action}')">Confirm ${word}</button>`;$('modal').classList.remove('hidden')}
async function adminModerate(steamId,action){const reason=$('modReason')?.value.trim()||'',confirmWord=$('modConfirm').value.trim();try{const r=await api('/portal/api/admin/moderate',{method:'POST',body:JSON.stringify({steamId,action,reason,confirm:confirmWord})});closeModal();toast(`✅ Verified complete: ${r.message||'Action completed.'}`)}catch(e){toast(e.message)}}
function refund(x){$('modalBody').innerHTML=`<h2>Refund Transaction</h2><p>${esc(x.player_name||x.steam_id)} • ${esc(x.title)}</p><div class="formgrid"><label>Refund amount<input id="refundAmount" type="number" min="1" max="${Math.abs(Number(x.amount))-Number(x.refunded_amount||0)}" value="${Math.abs(Number(x.amount))-Number(x.refunded_amount||0)}"></label><label class="full">Required reason<textarea id="refundReason" rows="4"></textarea></label></div><button class="btn primary" style="margin-top:12px" onclick="confirmRefund('${x.id}')">Issue Refund</button>`;$('modal').classList.remove('hidden')}
async function confirmRefund(id){const amount=Number($('refundAmount').value),reason=$('refundReason').value.trim();if(!reason)return toast('A refund reason is required.');try{await api('/portal/api/admin/refund',{method:'POST',body:JSON.stringify({transactionId:id,amount,reason})});closeModal();toast('Refund completed.');await loadAdminLedger();silentRefresh(true)}catch(e){toast(e.message)}}

let shopManagerProducts=[];let shopDraftItems=[];let shopCatalogSearchResults=[];
async function renderServerShopManager(a){a.innerHTML=`<div class="grid"><div class="card span12 manageHero"><div><small>OWNER CONTROLLED SUPPLY NETWORK</small><h2>Server Shop Manager</h2><p>Create packages, search the live GGCON item catalogue, choose quantities, change prices, and enable or disable products without editing code.</p></div><button class="btn primary" onclick="openShopProductEditor()">+ New Product</button></div><div class="card span12"><div class="searchbar"><input id="shopManagerFilter" placeholder="Search products or categories" oninput="filterShopManagerCards()"><button class="btn" onclick="loadShopManager()">Refresh</button></div><div class="shopManagerGrid" id="shopManagerGrid"><div class="empty">Loading products…</div></div></div></div>`;await loadShopManager()}
async function loadShopManager(){try{const r=await api('/portal/api/admin/shop/products');shopManagerProducts=r.products||[];drawShopManager()}catch(e){$('shopManagerGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function drawShopManager(){const box=$('shopManagerGrid');if(!box)return;box.innerHTML=shopManagerProducts.map((p,index)=>`<article class="card shopManagerCard" data-search="${esc(`${p.name} ${p.category} ${p.description}`.toLowerCase())}"><div class="shopManagerTop"><span class="shopEmoji">${esc(p.emoji||'📦')}</span><span class="status ${p.enabled?'good':''}">${p.enabled?'ENABLED':'DISABLED'}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description||'No description')}</p><small>${esc(p.category||'General')} • ${money(p.price)} • ${(p.items||[]).length} item types</small><div class="list compact">${(p.items||[]).slice(0,5).map(i=>`<div class="row"><span>${esc(i.label)}</span><b>×${Number(i.qty||1)}</b></div>`).join('')}${(p.items||[]).length>5?`<div class="empty">+${p.items.length-5} more</div>`:''}</div><div class="shopOrderControls"><button class="btn" onclick="moveShopProduct('${esc(p.id)}',-1)" ${index===0?'disabled':''} aria-label="Move product earlier">↑ Move Earlier</button><span>${index+1} of ${shopManagerProducts.length}</span><button class="btn" onclick="moveShopProduct('${esc(p.id)}',1)" ${index===shopManagerProducts.length-1?'disabled':''} aria-label="Move product later">Move Later ↓</button></div><div class="adminActions"><button class="btn primary" onclick="openShopProductEditor('${esc(p.id)}')">Edit</button><button class="btn" onclick="duplicateShopProduct('${esc(p.id)}')">Duplicate</button><button class="btn dangerBtn" onclick="deleteShopProduct('${esc(p.id)}','${esc(p.name)}')">Delete</button></div></article>`).join('')||'<div class="empty">No products configured.</div>'}
async function moveShopProduct(id,direction){const from=shopManagerProducts.findIndex(x=>String(x.id)===String(id));const to=from+Number(direction||0);if(from<0||to<0||to>=shopManagerProducts.length)return;const previous=[...shopManagerProducts];const [moved]=shopManagerProducts.splice(from,1);shopManagerProducts.splice(to,0,moved);drawShopManager();try{const r=await api('/portal/api/admin/shop/reorder',{method:'POST',body:JSON.stringify({orderedIds:shopManagerProducts.map(x=>x.id)})});shopManagerProducts=r.products||shopManagerProducts;drawShopManager();toast('Server Shop order updated.')}catch(e){shopManagerProducts=previous;drawShopManager();toast(e.message)}}
function filterShopManagerCards(){const q=$('shopManagerFilter').value.toLowerCase();document.querySelectorAll('#shopManagerGrid [data-search]').forEach(x=>x.style.display=x.dataset.search.includes(q)?'':'none')}
function duplicateShopProduct(id){const p=shopManagerProducts.find(x=>String(x.id)===String(id));if(!p)return;openShopProductEditor('',{...p,id:null,name:`${p.name} Copy`,slug:'',sortOrder:shopManagerProducts.length})}
function shopCategoryOptions(current='General'){const used=[...new Set(shopManagerProducts.map(x=>String(x.category||'General').trim()).filter(Boolean))];if(current&&!used.includes(current))used.push(current);if(!used.length)used.push('General');return used.sort((a,b)=>a.localeCompare(b)).map(c=>`<option value="${esc(c)}" ${c===current?'selected':''}>${esc(c)}</option>`).join('')}
function openShopProductEditor(id='',override=null){const p=override||shopManagerProducts.find(x=>String(x.id)===String(id))||{name:'',emoji:'📦',description:'',category:shopManagerProducts[0]?.category||'General',price:0,enabled:true,sortOrder:shopManagerProducts.length,items:[]};shopDraftItems=(p.items||[]).map(x=>({...x}));$('modalBody').innerHTML=`<h2>${p.id?'Edit':'Create'} Server Shop Product</h2><div class="formgrid"><label>Product name<input id="spName" value="${esc(p.name||'')}"></label><label>Emoji<input id="spEmoji" value="${esc(p.emoji||'📦')}" maxlength="16"></label><label>Category<select id="spCategory">${shopCategoryOptions(p.category||'General')}</select></label><label>Price<input id="spPrice" type="number" min="0" value="${Number(p.price||0)}"></label><label>Enabled<select id="spEnabled"><option value="true" ${p.enabled!==false?'selected':''}>Yes</option><option value="false" ${p.enabled===false?'selected':''}>No</option></select></label><label class="full">Description<textarea id="spDescription" rows="3">${esc(p.description||'')}</textarea></label></div><p class="formHint">Product placement is changed from the Server Shop Manager using Move Earlier and Move Later.</p><div class="catalogBuilder"><div class="builderHead"><div><small>LIVE GGCON ITEM CATALOGUE</small><h3>Package Contents</h3></div></div><div class="searchbar"><input id="catalogSearch" placeholder="Search item name or internal spawn ID" onkeydown="if(event.key==='Enter')searchShopItems()"><button class="btn" onclick="searchShopItems()">Search Inventory</button></div><div id="catalogResults" class="catalogResults"></div><h4>Selected Items</h4><div id="shopDraftItems" class="list"></div></div><div class="modalFooter"><button class="btn primary" onclick="saveShopProduct('${esc(p.id||'')}',${Number(p.sortOrder||0)})">Save Product</button><button class="btn" onclick="closeModal()">Cancel</button></div>`;$('modal').querySelector('.modal').classList.add('detailModal');$('modal').classList.remove('hidden');const draftName=`serverShopProduct:${p.id||'new'}`;restoreDraft(draftName,{extraRestore:d=>{if(Array.isArray(d.shopDraftItems))shopDraftItems=d.shopDraftItems.map(x=>({...x}))}});drawShopDraftItems();armDraft(draftName,()=>({shopDraftItems}));$('catalogResults').innerHTML='<div class="empty">Type at least 2 characters to search the SCUM catalogue.</div>'}
async function searchShopItems(){const q=($('catalogSearch')?.value||'').trim();const box=$('catalogResults');if(!box)return;if(q.length<2){box.innerHTML='<div class="empty">Type at least 2 characters to search the SCUM catalogue.</div>';return}box.innerHTML='<div class="empty">Searching cached inventory…</div>';try{const r=await api(`/portal/api/admin/shop/items?q=${encodeURIComponent(q)}`);shopCatalogSearchResults=r.items||[];box.innerHTML=shopCatalogSearchResults.map((i,n)=>`<button class="catalogItem" onclick="addShopDraftItem(shopCatalogSearchResults[${n}])">${i.iconUrl?`<img class="catalogIcon" src="${esc(i.iconUrl)}" alt="" loading="lazy" onerror="this.replaceWith(Object.assign(document.createElement('span'),{textContent:'📦'}))">`:'<span class="catalogIconFallback">📦</span>'}<div><b>${esc(i.label)}</b><small>${esc(i.itemClass)} • ${esc(i.category||'SCUM Item')}</small></div><strong>ADD</strong></button>`).join('')||'<div class="empty">No matching SCUM items.</div>'}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function addShopDraftItem(item){const existing=shopDraftItems.find(x=>x.itemClass===item.itemClass);if(existing)existing.qty=Math.min(1000,Number(existing.qty||1)+1);else shopDraftItems.push({label:item.label,itemClass:item.itemClass,qty:1,icon:item.icon||null,iconUrl:item.iconUrl||null,category:item.category||null});drawShopDraftItems()}
function drawShopDraftItems(){const box=$('shopDraftItems');if(!box)return;box.innerHTML=shopDraftItems.map((i,n)=>`<div class="row shopDraftRow"><div class="shopDraftItem">${i.iconUrl?`<img class="catalogIcon" src="${esc(i.iconUrl)}" alt="" loading="lazy" onerror="this.style.display='none'">`:'<span class="catalogIconFallback">📦</span>'}<div><b>${esc(i.label)}</b><small>${esc(i.itemClass)}${i.category?` • ${esc(i.category)}`:''}</small></div></div><div class="qtyControl"><button class="btn" onclick="changeShopQty(${n},-1)">−</button><input type="number" min="1" max="1000" value="${Number(i.qty||1)}" onchange="setShopQty(${n},this.value)"><button class="btn" onclick="changeShopQty(${n},1)">+</button><button class="btn dangerBtn" onclick="removeShopDraftItem(${n})">Remove</button></div></div>`).join('')||'<div class="empty">Search the inventory and add at least one item.</div>'}
function changeShopQty(n,d){shopDraftItems[n].qty=Math.max(1,Math.min(1000,Number(shopDraftItems[n].qty||1)+d));drawShopDraftItems()}function setShopQty(n,v){shopDraftItems[n].qty=Math.max(1,Math.min(1000,Math.floor(Number(v||1))))}function removeShopDraftItem(n){shopDraftItems.splice(n,1);drawShopDraftItems()}
async function saveShopProduct(id,sortOrder=0){const body={id:id||null,name:$('spName').value.trim(),emoji:$('spEmoji').value.trim()||'📦',category:$('spCategory').value||'General',price:Number($('spPrice').value),sortOrder:Number(sortOrder||0),enabled:$('spEnabled').value==='true',description:$('spDescription').value.trim(),items:shopDraftItems};if(!body.name||!body.items.length)return toast('Add a product name and at least one item.');try{await api('/portal/api/admin/shop/product',{method:'POST',body:JSON.stringify(body)});closeModal();clearDraft(`serverShopProduct:${id||'new'}`);toast('Server shop product saved.');await refresh();adminTab('serverShop')}catch(e){toast(e.message)}}
async function deleteShopProduct(id,name){if(!confirm(`Delete ${name} permanently?`))return;try{await api('/portal/api/admin/shop/delete',{method:'POST',body:JSON.stringify({id})});toast('Product deleted.');await refresh();adminTab('serverShop')}catch(e){toast(e.message)}}
async function renderOwnerControls(a){title('OWNER OPERATIONS','Owner Control Center');if(!state.me.isOwner){a.innerHTML='<div class="card empty">Owner access required.</div>';return}a.innerHTML=`<div class="grid"><div class="card span12 ownerControlHero"><small>OWNER EYES ONLY</small><h2>Command Center Configuration</h2><p>Manage non-secret portal settings without editing Railway variables. Tokens and passwords stay in Railway.</p></div><div class="card span12"><h3>Admin Permissions</h3><div id="permissionGrid" class="permissionGrid"><div class="empty">Loading permissions…</div></div><div class="adminActions"><button class="btn primary" onclick="saveOwnerPermissions()">Save Permission Changes</button><button class="btn" onclick="restorePermissionDefaults()">Restore Recommended Defaults</button></div></div><div class="card span12"><div class="cardHeading"><div><small>PORTAL CONTROLS</small><h3>Notices and Feature Switches</h3></div></div><div id="ownerSettings"><div class="empty">Loading configuration…</div></div></div></div>`;loadOwnerSettings();try{const r=await api('/portal/api/owner/permissions');state.ownerPermissions=r.permissions||{};state.permissionCatalog=r.catalog||[];drawPermissionGrid()}catch(e){$('permissionGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function drawPermissionGrid(){const box=$('permissionGrid');box.innerHTML=`<div class="permissionHeader"><b>Tool</b><b>Owner</b><b>Admin</b></div>${state.permissionCatalog.map(x=>`<label class="permissionRow ${x.dangerous?'dangerPermission':''}"><span><b>${esc(x.label)}</b>${x.dangerous?'<small>Powerful permission — enable carefully</small>':''}</span><input type="checkbox" checked disabled aria-label="Owner always allowed"><input class="adminPerm" data-key="${esc(x.key)}" type="checkbox" ${state.ownerPermissions[x.key]?'checked':''}></label>`).join('')}`}
function restorePermissionDefaults(){for(const x of state.permissionCatalog)state.ownerPermissions[x.key]=x.defaultAdmin===true;drawPermissionGrid();toast('Recommended defaults loaded. Save to apply them.')}
async function saveOwnerPermissions(){const permissions={};document.querySelectorAll('.adminPerm').forEach(x=>permissions[x.dataset.key]=x.checked);const dangerousEnabled=state.permissionCatalog.filter(x=>x.dangerous&&permissions[x.key]&&!state.ownerPermissions[x.key]);if(dangerousEnabled.length&&!confirm(`Enable ${dangerousEnabled.length} powerful Admin permission(s)?`))return;try{await api('/portal/api/owner/permissions',{method:'POST',body:JSON.stringify({permissions})});state.ownerPermissions=permissions;state.me.permissions=permissions;toast('Admin permissions updated.');nav()}catch(e){toast(e.message)}}

function closeModal(){if(saveDraft.active?.save)saveDraft.active.save();saveDraft.active=null;const modal=$('modal').querySelector('.modal');modal.classList.remove('detailModal');$('modal').classList.add('hidden')}
async function refresh(){const ui=preserveUi();state.data=await api('/portal/api/overview');state.me=state.data.me;state.overviewHash=stableHash(state.data);state.pendingPortalRefresh=false;render();if(state.section==='admin'&&ui.adminSubtab&&ui.adminSubtab!=='players')setTimeout(()=>adminTab(ui.adminSubtab),0);restoreUi(ui)}
$('refreshBtn').onclick=refresh;$('backBtn').onclick=goBack;$('homeBtn').onclick=goHome;updatePageNav();$('dismissSessionWarning')?.addEventListener('click',dismissSessionWarning);$('dismissMaintenance')?.addEventListener('click',dismissMaintenance);
loadServerWeather();setInterval(loadServerWeather,60000);load().catch(e=>{if(state.sessionExpired)return;document.body.innerHTML=`<div style="padding:40px;color:#ff8d8d"><h2>Command Center unavailable</h2><p>${esc(e.message)}</p><p>Please reopen the Command Center from Discord.</p></div>`});


async function loadOwnerSettings(){
  const box=$('ownerSettings');if(!box)return;
  try{const r=await api('/portal/api/owner/settings'),x=r.settings||{},f=x.features||{};box.innerHTML=`<div class="formGrid"><label>Banner title<input id="cfgTitle" value="${esc(x.maintenanceTitle||'WATCHER NOTICE')}"></label><label>Banner level<select id="cfgLevel"><option value="info" ${x.maintenanceLevel==='info'?'selected':''}>Info</option><option value="notice" ${x.maintenanceLevel==='notice'?'selected':''}>Notice</option><option value="critical" ${x.maintenanceLevel==='critical'?'selected':''}>Critical</option></select></label><label class="span2">Maintenance message<textarea id="cfgMessage" rows="3" placeholder="Leave blank to hide the banner">${esc(x.maintenanceMessage||'')}</textarea></label><label class="span2">Portal announcement<textarea id="cfgAnnouncement" rows="2" placeholder="Optional dashboard announcement">${esc(x.announcement||'')}</textarea></label></div><div class="featureSwitchGrid">${[['purchases','Server purchases'],['rentals','Dirtbike rentals'],['airlift','Airlift Taxi'],['insurance','Vehicle insurance'],['eventCreation','Event creation'],['surveillanceTeleport','Surveillance teleport']].map(([k,l])=>`<label class="featureSwitch"><input type="checkbox" data-feature="${k}" ${f[k]!==false?'checked':''}><span><b>${l}</b><small>${f[k]!==false?'Enabled':'Disabled'}</small></span></label>`).join('')}</div><div class="adminActions"><button class="btn primary" onclick="saveOwnerSettings()">Save Portal Configuration</button></div>`}catch(e){box.innerHTML=`<div class="empty">${esc(e.message)}</div>`}
}
async function saveOwnerSettings(){
  const features={};document.querySelectorAll('[data-feature]').forEach(x=>features[x.dataset.feature]=x.checked);
  try{const r=await api('/portal/api/owner/settings',{method:'POST',body:JSON.stringify({maintenanceTitle:$('cfgTitle').value,maintenanceMessage:$('cfgMessage').value,maintenanceLevel:$('cfgLevel').value,announcement:$('cfgAnnouncement').value,features})});state.data.settings=r.settings;toast('Portal configuration saved.');await silentRefresh(true)}catch(e){toast(e.message)}
}

async function loadActiveUnregisteredCount(){try{const d=await api('/portal/api/admin/unregistered-active');const el=$('unregisteredQuickCount');if(el)el.textContent=d.count?`${d.count} active player${d.count===1?'':'s'} need attention`:'No active unknown players';}catch{}}
